(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["af"] = {"ui":{"skip":"Spring na die inhoud","back":"← Terug na AI-gile","lang.button":"Taal: {name}","lang.dialog":"Kies 'n taal","lang.search":"Soek tale","lang.none":"Geen taal pas nie","lang.notYet":"{name} is nog nie vertaal nie","theme.aria":"Wissel tema: lig, donker of swart","theme.toLight":"Wissel na lig tema","theme.toDark":"Wissel na donker tema","theme.toBlack":"Wissel na swart tema (ware swart, sag op OLED-skerms)","words.underline":"Onderstreep hierdie woorde op die bladsy","words.underlineHelp":"Beweeg oor of tik op 'n gestippelde woord om te sien wat dit beteken.","words.col.todo":"Kaarte wat nou gekies is: die span begin hierdie volgende.","words.col.doing":"'n KI werk nou aan hierdie kaart.","words.col.review":"Een KI is klaar met die werk; 'n ander kyk dit na voordat dit by jou uitkom.","words.col.verify":"Wag vir jou: probeer dit uit en sê of dit werk.","words.col.team":"Jou notas of antwoorde, wat wag dat die span dit optel.","words.col.done":"Klaar en aanvaar.","index.title":"AI-gile: jou KI-ontwikkelaarspan, op een bord","index.description":"AI-gile is 'n kanban-bord vir KI-programmeerspanne. Hulle werk terwyl jy slaap; jy kry een kort hopie dinge om te besluit, te toets en te aanvaar.","hero.logoAlt":"AI-gile-bordikoon","hero.h1.html":"Jou KI-ontwikkelaarspan, op een&nbsp;bord.","hero.alpha":"🐣 Geslote pre-alfa","hero.alphaTitle":"Vroeg en onafgehandel: dankie dat jy dit probeer!","hero.lede":"Hulle bou terwyl jy slaap. Jy word wakker met een kort hopie: 'n paar vrae, 'n paar goed om te toets, een of twee pers diamante. Klik, aanvaar, terug na jou koffie.","dl.windows":"Windows-app","dl.browser":"Gebruik dit in jou blaaier","dl.messenger":"📱 Messenger vir jou foon","dl.soon":"Binnekort","dl.notify":"🔔 Laat weet my wanneer dit oopgaan","dl.notifySmall":"Alfa of beta","hero.secondary":"Agile, maar die span hoef nooit 'n stand-up-koffie te drink nie. (Hulle hou tog stand-ups.)","pitch.h2":"AI-gile in soveel woorde as jy wil","pitch.lede":"Kies 'n lengte, van een woord tot 144. Elke lengte is sy eie beskrywing, vir daardie grootte geskryf. Sleep die skuifbalk of gebruik die pyltjiesleutels.","pitch.rangeLabel":"Lengte in woorde","pitch.dice":"🎲 nog 'n weergawe","pitch.words.one":"{n} woord","pitch.words.other":"{n} woorde","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakters","count.line.html.one":"{n} kaart op die bord op die oomblik","count.line.html.other":"{n} kaarte op die bord op die oomblik","people.humans.html.one":"👥 {n} mens","people.humans.html.other":"👥 {n} mense","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agente","people.working.html.one":"⚡ {n} aan die werk op die oomblik","people.working.html.other":"⚡ {n} aan die werk op die oomblik","pre.title":"AI-gile: hier word iets gebou","pre.description":"Hier word iets gebou. 'n Bord waar KI-spanne bou wat jy vra, en jou leer terwyl hulle werk. Vir nou 'n geslote pre-alfa met vriende.","pre.h1":"Hier word iets gebou. 🤫","pre.line":"'n Bord waar KI-spanne bou wat jy vra, en jou leer terwyl hulle werk. Vir nou 'n geslote pre-alfa met vriende.","pre.btn":"🔔 Laat weet my wanneer dit oopgaan","pre.peek":"Agter die glas: die regte bord, regstreeks. Elke kaart is 'n gekleurde strook.","pre.peekFake":"Agter die glas: so lyk 'n bord wat aan die werk is.","pre.night":"🌙 Die nagwag is in beheer · 😴 die mens rus","features.aria":"Wat dit doen","f.pile.h":"Een hopie vir jou","f.pile.html":"<b>Vir jou</b> hou alles wat op jou wag, oor elke projek heen: vrae, goed om te toets, take wat net 'n mens kan doen. Jou tou sê wat volgende is en hoe lank dit neem.","f.sleep.h":"Spanne wat werk terwyl jy slaap","f.sleep.p":"Elke projek het 'n leier en 'n span KI-agente. Lewer kommentaar op 'n kaart en die span word wakker, doen die werk, en gee dit terug met stappe wat 'n moeë mens kan volg.","f.tester.h":"'n KI-toetser kyk eerste","f.tester.p":"Voordat enigiets by jou uitkom, volg 'n toetser die stappe in 'n kopie van die app en wys wat hy gesien het, met 'n skermkiekie. Blaai deur die geslaagdes en aanvaar met een klik.","f.proof.h":"Bewys, nie beloftes nie","f.proof.p":"Elke oorhandiging wys wat verander het: die lêers, die diff, die skermkiekies. Jy hoef nie elke app oop te maak om te sien of dit klaar is nie.","f.chat.h":"Gesels met jou leiers","f.chat.p":"'n Discord-agtige balk: een ikoon per projek, pers diamante vir wat jou nodig het. Stuur 'n leier 'n idee; hy maak dit kaarte en 'n plan, met 'n ✅ Gaan-knoppie.","f.tidy.h":"Hou homself netjies","f.tidy.p":"Verwante kaarte word een, deurmekaar titels word reggemaak, en 'n token-kontrole hou die kode skraal. Minder om tussen te wissel, minder om aan te dink.","f.private.h":"Joune, op jou rekenaar","f.private.li1":"Die bord loop op jou eie masjien en antwoord net vir jou.","f.private.li2":"Private DM's tussen mense is end-tot-end-geënkripteer.","f.private.li3":"Geen rekeninge, geen snuffelaars, geen koekies.","f.lang.h":"In jou taal","f.lang.p":"Meer as 120 tale, van Nederlands, Wallies en Japannees tot seerower, Yoda en Klingon, met 'n vinnige wissel terug na Engels vir die vakjargon.","f.service.h":"Van 'n idee tot 'n regte diens","f.service.p":"Iets met KI gebou wat mense nou gebruik? Merk dit as 'n diens en die bord help jou om dit goed te bedryf: beskikbaarheidskontroles, 'n openbare statusbladsy, voorvalle met 'n nabetragting, veranderings wat 'n Go nodig het, rugsteune wat daagliks nagegaan word. Hulp leer jou elke stap soos jy aangaan.","msgr.h2":"AI-gile Messenger: jou span in jou sak","msgr.p1":"Praat met jou KI-span sonder om die bord oop te maak. Klets met jou projekleiers en jou vriende, en sien 'n kaart se toetsstappe en beantwoord hulle, alles van jou foon af.","msgr.p2":"Om dit te koppel, skandeer 'n QR-kode op jou bord. Eerste keer? 'n Vriendelike demo-klets wys jou die pad.","msgr.when":"Eers Android, dan 'n webweergawe vir fone en iPhone.","msgr.who":"Jou projekleier","msgr.b1":"Die regstelling vir donkermodus is gereed. Wil jy die toetsstappe hê?","msgr.b2":"Ja asseblief!","msgr.b3":"1. Maak Instellings oop. 2. Kies Donker. Lyk dit reg?","tl.aria":"Tydlyn van die eerste gesprek tot die padkaart","tl.h2":"Van die eerste gesels tot wat volgende kom","tl.lede":"Regte datums en tye, in jou eie tydsone. Ná vandag is dit die plan, sonder beloofde datums.","tl.today":"Vandag","tl.planned":"beplan","tl.doing":"besig","tl.cards.one":"{n} kaart","tl.cards.other":"{n} kaarte","join.h2":"Doen saam","join.lede":"AI-gile word gebou deur 'n bebaarde eksentrieke ou met AuDHD en 'n paar geestesgesondheidstryde, en 'n groot klomp geduldige agente. Dit is vir eers privaat, in 'n geslote alfa met vriende. Wil jy 'n kans hê wanneer dit oopgaan?","join.btn":"Teken belangstelling in","join.small":"Ons stuur jou 'n e-pos, niks anders nie","footer.tag":"AI-gile. Geen snuffelaars, geen koekies, geen stand-up-koffie.","footer.licence":"Besigheidslisensie","footer.status":"Status","footer.privacy":"Wat ons hou","footer.thanks":"Oproepe danksy ChilledChat","form.sending":"Stuur tans…","form.failed":"Dit het nie gewerk nie: probeer later weer.","form.offline":"Kon nie AI-gile bereik nie: probeer later weer.","form.keep":"Ons gebruik dit net om jou te antwoord, en vee dit dan uit. Geen snuffelaars, geen koekies.","form.keepLink":"Wat ons hou","interest.title":"AI-gile: laat weet my wanneer die alfa oopgaan","interest.description":"Los jou e-pos om te hoor wanneer AI-gile se geslote alfa of beta oopgaan.","interest.h1":"🔔 Laat weet my wanneer dit oopgaan","interest.lede":"AI-gile is in geslote pre-alfa. Los jou e-pos en ons skryf een keer, wanneer daar 'n plek vir jou is.","interest.email":"Jou e-pos","interest.which":"Watter toets?","interest.alpha":"Geslote alfa: vroeg, rof, baie veranderinge","interest.beta":"Beta: bestendiger, later","interest.both":"Enige een, wat ook al eerste kom","interest.submit":"Sit my op die lys","interest.thanks":"Dankie! Jy is op die lys.","licence.title":"AI-gile: besigheidslisensie","licence.description":"Gebruik jy AI-gile in jou besigheid? Doen aansoek om 'n gratis besigheidslisensie.","licence.h1":"📜 Besigheidslisensie","licence.lede":"Gebruik jy AI-gile by die werk? Vertel ons wie jy is en wat jy doen. As dit 'n bietjie goed doen, is die lisensie gratis.","licence.company":"Maatskappy","licence.website":"Webwerf","licence.what":"Wat jy doen","licence.how":"Hoe dit die wêreld help","licence.email":"E-pos","licence.submit":"Doen aansoek","licence.thanks":"Dankie! Ons antwoord per e-pos.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alles rustig","status.intro":"Werk AI-gile nou? Hierdie bladsy kyk elke 5 minute na die webwerf, borddeling, oproepe en die aflaai.","status.up":"Werk (het in {ms} ms geantwoord)","status.slow":"Het nie op die laaste kontrole geantwoord nie, probeer weer","status.down":"Af: het nie op die laaste twee kontroles geantwoord nie","status.svc.web":"Webwerf","status.svc.web.offers":"Hierdie werf: wat AI-gile is, en die belangstellingsvorm","status.svc.boards":"Borddeling","status.svc.boards.offers":"Openbare borde, boodskappe tussen vriende en uitnodigings","status.svc.calls":"Oproepe","status.svc.calls.offers":"Stem, video en skermdeling in AI-gile","status.svc.download":"Aflaai","status.svc.download.offers":"Die Windows-installeerder en uitnodigingskakels","status.checking":"Kyk tans…","status.offline":"Kan die statusdiens nou nie bereik nie (probeer weer)","status.updated":"opgedateer {ago}","status.justNow":"nou net","status.min":"{n} min gelede","status.hours":"{n} u gelede","status.days":"{n} d gelede","privacy.title":"AI-gile: wat ons hou","privacy.h1":"Wat ons hou","privacy.lede":"Kort weergawe: net wat jy vir ons stuur, en nie vir lank nie.","privacy.only":"Net wat jy vir ons stuur: wat jy in 'n vorm intik, soos jou e-pos. Niks anders oor jou nie.","privacy.sealed":"Dit word verseël sodat ons bediener dit nie kan lees nie: in jou blaaier voordat dit vertrek (op 'n ouer blaaier, die oomblik wat dit aankom). Net ons eie bord kan dit oopmaak.","privacy.server":"Dit word van die bediener uitgevee sodra dit ons bord bereik. Enigiets wat ná 30 dae nog daar is, word in elk geval uitgevee.","privacy.board":"Ons hou dit net op ons bord totdat ons jou geantwoord het, en vee dit dan daar ook uit.","privacy.none":"Geen snuffelaars, geen koekies, geen analitika.","privacy.local":"Jou taal en lig- of donkerkeuse bly in jou eie blaaier. Dit word nooit na ons gestuur nie.","privacy.ask":"Wil jy hê dit moet gouer weg wees? Antwoord op ons e-pos en sê so.","live.h2":"Kyk hoe dit gebou word, regstreeks","live.caption":"Elke kaart is versteek: jy sien die vorm van die werk, nie die woorde nie.","live.watching.one":"regstreeks: {n} kyk","live.watching.other":"regstreeks: {n} kyk","live.last.now":"Laaste kaart pas verskuif","live.last.min.one":"Laaste kaart {n} min gelede verskuif","live.last.min.other":"Laaste kaart {n} min gelede verskuif","live.last.hour.one":"Laaste kaart {n} uur gelede verskuif","live.last.hour.other":"Laaste kaart {n} uur gelede verskuif","live.last.day.one":"Laaste kaart {n} dag gelede verskuif","live.last.day.other":"Laaste kaart {n} dae gelede verskuif","live.offline":"Die lewendige bord haal asem. Kom kyk gou weer.","live.cols":"Backlog|Om te doen|Besig|Span kontroleer|Vir jou om te toets|Vir die span|Klaar"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotte.","Uitbestee."]},{"n":2,"texts":["Robotte-kanban, gratis.","Agente, georganiseer.","Idees, gebou."]},{"n":3,"texts":["Kanban vir robotte.","Idees word funksies.","Gratis agent-kanban."]},{"n":5,"texts":["Kanban-bord wat agente bestuur.","Jy skryf kaarte. Agente bou.","Gratis, plaaslik, getoets, effens simpel."]},{"n":8,"texts":["'n Gratis kanban-bord waar KI-agente werk doen.","Skryf 'n idee. Agente bou dit. Jy aanvaar.","Agile vir een mens en baie geduldige robotte."]},{"n":13,"texts":["'n Kanban-bord op jou rekenaar waar KI-agente die kaarte optel en afhandel.","Skryf 'n idee. 'n Span agente bou dit. 'n Toetser kyk dit na.","Gratis, geen rekeninge, geen snuffelaars: 'n bord, 'n paar robotte, en jy aan die stuur."]},{"n":21,"texts":["AI-gile is 'n kanban-bord om saam met KI-programmeeragente te werk. Hulle tel die kaarte op; jy toets en aanvaar dit.","Elke projek kry 'n leier en 'n span KI-agente. Lewer kommentaar op enige kaart en die span gaan aan die werk.","'n Gratis, persoonlike taakbord wat op jou eie rekenaar loop. Die werkers is robotte. Die een wat ja sê, is jy."]},{"n":34,"texts":["Jy sit idees op 'n bord. 'n Span KI-agente maak daarvan werkende funksies, toets dit, en gee dit terug met stappe om te probeer. Niks tel as klaar totdat jy dit sê nie.","AI-gile is 'n tuisgemaakte kanban-bord wat Rich gebou het met baie hulp van die agente wat dit nou bestuur. Dit is gratis, loop op jou rekenaar, en word met vriende gedeel, nie verkoop nie.","Dink aan 'n gewone kanban-bord, met kolomme van Backlog tot Klaar, behalwe dat KI-agente die kaarte optel. Hulle rapporteer vordering, vra vrae as hulle vassit, en wag altyd vir jou duim in die lug."]},{"n":55,"texts":["AI-gile is 'n kanban-bord waar die span uit KI-agente bestaan. Elke projek het 'n leier wat die werk beplan en helpers wat dit bou. Wanneer 'n funksie gereed is, probeer 'n KI-toetser dit en neem 'n skermkiekie, dan beland dit in jou hopie. Aanvaar dit, of lewer kommentaar en hulle werk dit oor.","Dit het begin as een persoon se manier om baie KI-programmeersessies gelyktydig dop te hou, en het gegroei tot 'n regte bord. Dit loop op jou masjien, vra geen rekening nie, en het geen snuffelaars nie. Dit is gratis vir vriende en enigeen wat nuuskierig is. Dit is ook onafgehandel, so verwag rowwe kante en die af en toe verrassing.","Hier is die eerlike weergawe. Jy moet steeds die idees hê, en jy moet steeds die resultate nagaan. Wat AI-gile doen, is alles tussenin: dit hou die kaarte in orde, wek die regte agent wanneer jy kommentaar lewer, wys presies wat verander het, en hou alles in een kort hopie vir jou."]},{"n":89,"texts":["AI-gile is 'n gratis kanban-bord wat jy op jou eie rekenaar laat loop. In plaas van mense het elke projek 'n span KI-agente: 'n leier wat jou idees in kaarte en 'n plan omskep, en helpers wat die kaarte in volgorde van prioriteit optel. Wanneer iets gebou is, volg 'n KI-toetser die toetsstappe en wys jou wat hy gesien het. Dan wag dit in een hopie gemerk Vir jou. Jy aanvaar dit, of jy lewer kommentaar en die span probeer weer. Niks kom ooit by Klaar uit sonder jou nie.","Party funksies verwag jy dalk nie. 'n Nagwag hou die kolom Om te doen aangevul terwyl jy slaap, en kies kaarte wat nie 'n antwoord van jou nodig het nie. 'n Tokenteller wys hoeveel die agente vandag en hierdie week gebruik het, en Geen-Token-Modus sê vir hulle om op te hou spandeer. Jy kan vriende boodskappe stuur, en private boodskappe is end-tot-end-geënkripteer. Die bord praat sowat 120 tale, onder andere Nederlands, Vlaams, seerower en Klingon. Niks daarvan kos 'n sent nie, en niemand probeer dit ook vir jou verkoop nie.","AI-gile is 'n klein, persoonlike projek, nie 'n maatskappy nie. Rich wou na etlike KI-programmeerprojekte omsien sonder om elke app oop te maak om daarna te kyk, so hy en die agente het 'n bord daarvoor gebou, en toe die bord gebruik om die res van homself te bou. Dit is in geslote pre-alfa, wat beteken dit werk, meestal, vir 'n handjievol vriende. Daar is geen pryslys, geen nuusbrief en geen groeiplan nie. As dit nuttig klink, kan jy vra om dit te probeer wanneer dit 'n bietjie verder oopgaan."]},{"n":144,"texts":["AI-gile is 'n kanban-bord vir een mens en 'n klomp KI-agente. Dit loop op jou eie rekenaar en dit is heeltemal gratis. Jy voeg projekte by, en elke projek kry 'n leier en 'n klein span. Jy gesels met die leier, 'n bietjie soos op Discord, en beskryf 'n idee; die leier maak dit kaarte en 'n plan, en wag dan dat jy Gaan druk. Die span werk die kaarte in volgorde van prioriteit af, met 'n eenvoudige opdragreël wat vir taalmodelle gemaak is. Voordat enigiets na jou terugkom, volg 'n KI-toetser die stappe in 'n kopie van die app en heg 'n skermkiekie aan. Klaargemaakte werk beland in jou hopie met die veranderde lêers en die diff. Jy aanvaar dit, of jy los 'n kommentaar en die span word wakker en probeer weer. Net jy kan 'n kaart na Klaar skuif.","'n Dag met AI-gile, ongeveer. In die aand los jy 'n paar kommentare: hierdie knoppie is op die verkeerde plek, daardie lys moet gesorteer wees, kan ons 'n donker modus kry. Jy gaan slaap. Die agente lees die kommentare, maak die veranderinge, toets dit en gee dit aan jou terug. As Om te doen leegloop, vul die nagwag dit uit die backlog met kaarte wat geen antwoord van jou nodig het nie. In die oggend is daar een kort hopie: 'n paar vrae en 'n paar goed om te probeer, elk met stappe wat 'n slaperige mens kan volg en 'n skermkiekie wat wys dit werk. Jy klik deur, aanvaar die goeies en stuur die res terug. 'n Tokenteller wys wat alles gebruik het, en Geen-Token-Modus is daar vir maer weke. Dan eet jy ontbyt, waarmee die agente nog nie kan help nie.","Eerstens, wat AI-gile nie is nie. Dit is nie 'n begin-maatskappy nie, dit is nie te koop nie, en niemand versamel jou data nie. Dit is 'n gratis bord wat op jou rekenaar loop, sonder rekeninge, snuffelaars of koekies. Wat dit wel is: een netjiese plek om elke KI-programmeerprojek gelyktydig te sien, met 'n span agente wat die kaarte doen en jy wat die besluite neem. Dit voeg verwante kaarte saam, maak deurmekaar titels reg, en hou dop hoe skraal die kode bly. Dit praat sowat 120 tale, van Nederlands en Vlaams tot seerower en Klingon. Vriende kan mekaar boodskappe stuur, privaat en geënkripteer. Dit is gebou deur Rich en 'n groot klomp geduldige agente, meestal deur homself te gebruik. Dit is in geslote pre-alfa, so dit is op plekke rof. As dit na pret klink, vra mooi en jy kan dalk vroeg inkom."]}],"quips":{"1":"Een woord. Gewaagd. Dalk te gewaagd.","3":"Drie woorde. Reeds eerliker as die meeste produkbladsye.","8":"Agt woorde. Steeds korter as 'n stand-up.","21":"Die lengtes is storiepunte, terloops. Natuurlik is hulle.","55":"Vyf-en-vyftig woorde. Twee kaarte is klaar terwyl jy dit gelees het.","144":"Dis die lang een. Daar is geen 233 nie. Die agente is gaan slaap."}},"timeline":{"first-idea.name":"Die eerste idee","first-idea.line":"Die allereerste gesprek, voordat daar enige kode was.","first-board.name":"Eerste bord","first-board.line":"'n Bord wat sy eie bou naspoor: kaarte, kolomme, sleep-en-los, projekte.","team-roles.name":"Span en rolle","team-roles.line":"Agentprofiele, spansjablone, ruimtes en wie wat doen.","install.name":"Installeer en weergawes","install.line":"'n Zip wat 'n vriend kan installeer, selfopdatering, kanale en terugrol.","usage-saver.name":"Gebruiksbespaarder","usage-saver.line":"Meet wat lopies kos, hou die kode skraal, spaar jou limiet.","friends.name":"Vriende en deel","friends.line":"Private DM's, 'n versleutelde relay, uitnodigings, rolle en gedeelde projekte.","languages.name":"Tale","languages.line":"Elke skermteks in 'n taallêer, met Nederlands en Vlaams eerste.","ai-tester.name":"KI-toetser","ai-tester.line":"'n Toetser kyk elke oorhandiging eerste na en wys wat hy gesien het.","website.name":"Die webwerf","website.line":"aigile.lol, die teaser en hierdie tydlyn.","streaming.name":"Klets en stroming","streaming.line":"Discord, Twitch, OBS, stroomermodus, GIF's en emoji's.","no-ai.name":"Sonder-KI-uitgawe","no-ai.line":"'n Bord vir mense wat sonder KI programmeer, en openbare borde.","night-watch.name":"Nagwag","night-watch.line":"'n Wag en Scrum Master hou die spanne op koers terwyl jy slaap.","p-more.name":"Alles anders","p-more.line":"Kleiner idees wat nog op hul beurt wag.","p-android.name":"Foon en Android","p-android.line":"Bereik jou bord vanaf 'n foon, dan 'n eie Android-app.","p-release.name":"Alfa en verder","p-release.line":"Geslote alfa, die lewendige werf, dan beta.","p-languages.name":"Meer tale","p-languages.line":"130 tale, en 'n onderdompelingsmodus vir leerders.","p-engines.name":"Meer KI-enjins","p-engines.line":"Kies Claude, Codex, Gemini, Copilot of Cursor per agent.","p-pro.name":"Professionele praktyk","p-pro.line":"Risikoetikette, samevoegpoorte, voorvalkaarte en leuningrelings.","p-self.name":"Na jou omsien","p-self.line":"Moeë-modus, selfsorg-herinnerings en 4:20.","p-servers.name":"Bedieners en skaal","p-servers.line":"Globale bedienerinstellings, rolle en beplanning vir groei.","p-livestream.name":"Stroom-ekstras","p-livestream.line":"Twitch-klets, eie emoji's en 'n openbare regstreekse blik."},"words":{"button":"📖 Vakjargon","h":"📖 Woorde verduidelik","intro":"Gratis opleiding in gewone taal: elke woord wat jy teëkom, van 'n eerste idee tot 'n diens waarop mense staatmaak, met Agile, bou, dit veilig hou en werk met KI onderweg.","search":"Soek 'n woord…","none":"Geen woord stem daarmee ooreen nie.","close":"Maak toe","count":{"one":"{count} woord","other":"{count} woorde"},"groups":[{"id":"idea","name":"💡 Idee en ontdekking"},{"id":"plan","name":"🗺️ Die werk beplan"},{"id":"agile","name":"🔁 Agile werkswyses"},{"id":"build","name":"🛠️ Dit bou"},{"id":"test","name":"🧪 Toetsing en gehalte"},{"id":"change","name":"🔀 Dit veilig verander"},{"id":"run","name":"🛎️ 'n Diens bedryf"},{"id":"sec","name":"🔒 Sekuriteit en privaatheid"},{"id":"ai","name":"🤖 Werk met KI"},{"id":"money","name":"💰 Geld en lisensies"}],"list":[{"id":"discovery","g":"idea","word":"Ontdekking (Discovery)","text":"Die vroeë stadium waar jy uitvind watter probleem die moeite werd is om op te los en vir wie, voordat enigiets gebou word.","also":["ontdekkingsfase","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Probleemstelling","text":"Een of twee sinne wat sê wie 'n probleem het, wat dit is en hoekom dit saak maak, sodat almal op dieselfde ding mik.","also":["probleemstellings","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Gebruiker","text":"'n Mens wat gebruik wat jy bou. Hul behoeftes is waarvoor die werk is.","also":["gebruikers","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Belanghebbende (Stakeholder)","text":"Enigiemand vir wie dit saak maak hoe die werk uitdraai of wat daardeur geraak word, soos die mense wat dit betaal, gebruik of ondersteun.","also":["belanghebbendes","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"'n Versonne maar lewensgetroue persoon wat een soort gebruiker verteenwoordig, sodat die span kan vra: “Sal Sam dit maklik vind?”","also":["persona's","personas"]},{"id":"userresearch","g":"idea","word":"Gebruikersnavorsing","text":"Met regte mense praat en hulle dophou om te leer wat hulle nodig het, in plaas van te raai.","also":["gebruikersonderhoude","user research","user interviews"]},{"id":"journey","g":"idea","word":"Gebruikersreis (User journey)","text":"Die stappe wat iemand neem om iets gedoen te kry, van die eerste keer dat hulle daarvan hoor tot dit klaar is, ook buite jou produk. As jy dit uitteken, sien jy waar hulle vashaak.","also":["gebruikersreise","kliëntreis","user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pynpunt (Pain point)","text":"Iets wat mense vandag ergerlik maak of vertraag. Goeie produkte neem pynpunte weg.","also":["pynpunte","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Aanname","text":"Iets wat jy glo maar nog nie nagegaan het nie. As jy aannames neerskryf, sien jy wat eerste getoets moet word.","also":["aannames","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipotese","text":"'n Beste raaiskoot wat jy beplan om na te gaan, saam met wat jy verwag sal gebeur, soos “mense sal inteken as die eerste maand gratis is”.","also":["hipoteses","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Eksperiment","text":"'n Klein beplande toets om te leer of 'n idee werk, voordat jy baie daarop wed.","also":["eksperimente","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Konsepbewys (PoC)","text":"'n Vinnige growwe poging om te sien of 'n idee enigsins kan werk. Dit word gewoonlik weggegooi sodra jy die antwoord het.","also":["PoC","proof of concept","konsepbewyse"]},{"id":"prototype","g":"idea","word":"Prototipe","text":"'n Vroeë model van die produk, dikwels klikbare prente, om die idee op mense te probeer voordat jy dit behoorlik bou.","also":["prototipes","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Draadraam (Wireframe)","text":"'n Eenvoudige skets van 'n skerm wat wys waar dinge heen gaan, sonder kleure of regte inhoud.","also":["draadrame","wireframes"]},{"id":"mockup","g":"idea","word":"Modelontwerp (Mockup)","text":"'n Gedetailleerde prent van hoe 'n skerm sal lyk, met regte kleure en teks, maar niks werk nog nie.","also":["mockups","mock-up","mock-ups","modelontwerpe"]},{"id":"bizcase","g":"idea","word":"Besigheidsgeval (Business case)","text":"Die redes om 'n projek te doen: wat dit kos, wat dit inbring of bespaar, en die risiko's.","also":["besigheidsgevalle","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Haalbaarheid","text":"Of iets werklik gebou en in stand gehou kan word met die tyd, geld en vaardighede wat jy het.","also":["haalbaar","feasibility"]},{"id":"outcome","g":"idea","word":"Uitkoms","text":"Die verandering wat jy vir mense wil hê, soos minder gemiste afsprake. Dit tel swaarder as hoeveel jy bou.","also":["uitkomste","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Uitset (Output)","text":"Iets wat die span maak, soos 'n nuwe skerm of 'n verslag. Dat dit gemaak is, beteken nie vanself dat dit iemand help nie.","also":["uitsette","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Sukses-maatstaf","text":"'n Getal wat jou sê of die werk gedoen het waarvoor dit bedoel was, soos meer mense wat hul bestelling voltooi.","also":["sukses-maatstawwe","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Sleutelprestasie-aanwyser (KPI)","text":"'n Belangrike getal wat jy dophou om te sien of dinge goed gaan, soos inskrywings per week.","also":["KPI","KPIs","key performance indicator","sleutelprestasie-aanwysers"]},{"id":"okr","g":"idea","word":"Doelwitte en sleutelresultate (OKR's)","text":"'n Manier om doelwitte te stel: die doelwit sê wat jy wil hê, en 'n paar sleutelresultate is die getalle wat wys jy het dit bereik.","also":["OKR","OKRs","OKR's"]},{"id":"product","g":"plan","word":"Produk","text":"Die ding wat vir sy gebruikers gebou en versorg word, soos 'n app, 'n webwerf of 'n hulpmiddel.","also":["produkte","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Produkvisie","text":"'n Kort verklaring van wie die produk help en waarheen dit oor die lang termyn op pad is.","also":["visieverklaring","product vision","vision statement"]},{"id":"po","g":"plan","word":"Produkeienaar (PO)","text":"Die persoon wat besluit wat gebou word en in watter volgorde, sodat die span altyd aan die belangrikste werk is. In AI-gile is dit jy.","also":["PO","product owner","product owners","produkeienaars"]},{"id":"pm","g":"plan","word":"Produkbestuurder (PM)","text":"Die persoon wat na 'n produk se rigting kyk: watter probleme dit oplos, vir wie en hoekom. PM kan ook projekbestuurder beteken, so maak seker watter een.","also":["produkbestuurders","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"Projekbestuurder","text":"Die persoon wat 'n projek betyds en binne begroting hou en dophou wie wat doen en teen wanneer.","also":["projekbestuurders","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Padkaart (Roadmap)","text":"'n Growwe plan van wat oor die volgende maande kom, in volgorde. Dit wys rigting, nie presiese datums nie, en verander soos jy leer.","also":["padkaarte","roadmaps"]},{"id":"milestone","g":"plan","word":"Mylpaal","text":"'n Punt in 'n projek wat dit werd is om te merk, soos “eerste weergawe aanlyn” of “100 gebruikers”.","also":["mylpale","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Minimum lewensvatbare produk (MVP)","text":"Die kleinste weergawe van 'n produk wat steeds nuttig is vir regte mense, sodat jy vroeg by hulle kan leer.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Vereiste","text":"Iets wat die voltooide produk moet doen of wees.","also":["vereistes","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Omvang (Scope)","text":"Wat by die werk ingesluit is en, ewe belangrik, wat nie.","also":["binne omvang","buite omvang","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Omvangskruip (Scope creep)","text":"Wanneer al meer en meer stukkie vir stukkie by die werk bykom, sonder dat iemand op die ekstra tyd of koste ooreengekom het, sodat dit nooit regtig klaar word nie.","also":["feature creep","kenmerkskruip"]},{"id":"feature","g":"plan","word":"Kenmerk (Feature)","text":"Een ding wat die produk vir mense kan doen, soos “stel jou wagwoord terug”.","also":["kenmerke","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epiek (Epic)","text":"'n Groot stuk werk, te groot vir een slag, daarom word dit in kleiner kaarte opgedeel.","also":["epieke","epic","epics"]},{"id":"story","g":"plan","word":"Gebruikersverhaal (User story)","text":"'n Klein stukkie werk wat uit die gebruiker se oogpunt geskryf is: “As inkoper wil ek my mandjie stoor, sodat ek later kan klaarmaak.” Dit begin 'n gesprek oor wat om te bou.","also":["gebruikersverhale","user story","user stories"]},{"id":"ac","g":"plan","word":"Aanvaardingskriteria (AC)","text":"Die toetse wat een kaart moet slaag om as klaar te tel, ooreengekom voordat die werk begin, soos “die mandjie is steeds daar nadat ek uit- en weer ingeteken het”.","also":["AC","acceptance criteria"]},{"id":"task","g":"plan","word":"Taak","text":"'n Enkele werkie wat gedoen moet word, dikwels een klein stap van 'n groter verhaal.","also":["take","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Kaartjie (Ticket)","text":"'n Ander woord vir 'n kaart: een stuk werk of een versoek, wat van begin tot einde gevolg word.","also":["kaartjies","ticket","tickets"]},{"id":"priority","g":"plan","word":"Prioriteit","text":"Hoe belangrik of dringend iets is in vergelyking met alles anders, sodat die belangrikste werk eerste gedoen word.","also":["prioriteite","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisering","text":"Werk in volgorde van belangrikheid plaas. 'n Algemene manier is MoSCoW: Must have (moet hê), Should have (behoort te hê), Could have (kan hê), Won't have (hierdie keer nie).","also":["prioritiseer","MoSCoW"]},{"id":"estimate","g":"plan","word":"Skatting","text":"'n Beste raaiskoot van hoe groot 'n stuk werk is of hoe lank dit gaan neem. Dit is 'n raaiskoot, nie 'n belofte nie.","also":["skattings","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Verhaalpunte (Story points)","text":"'n Manier om die grootte van werk te raai deur kaarte met mekaar te vergelyk (“omtrent twee keer so groot soos daardie een”) eerder as in ure. Hulle is nie om spanne met mekaar te vergelyk nie.","also":["verhaalpunt","story point"]},{"id":"tshirt","g":"plan","word":"T-hemp-groottes (T-shirt sizing)","text":"Die grootte van werk raai as S, M, L of XL. Vinnig en goed genoeg vir vroeë beplanning.","also":["t-hemp-groottes","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Beplanningspoker (Planning poker)","text":"'n Speletjie om te skat: almal wys terselfdertyd 'n grootte-kaart, en dan verduidelik die hoogste en die laagste hoekom.","also":["Scrum poker","Scrum-poker"]},{"id":"dependency","g":"plan","word":"Afhanklikheid","text":"Wanneer een stuk werk nie kan begin of klaarmaak voordat 'n ander een dit doen nie.","also":["afhanklikhede","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Struikelblok (Blocker)","text":"Enigiets wat verhoed dat werk nou vorentoe beweeg, soos 'n ontbrekende antwoord of 'n gebreekte hulpmiddel.","also":["struikelblokke","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Sperdatum (Deadline)","text":"Die datum waarteen iets klaar moet wees.","also":["sperdatums","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Lewerbare (Deliverable)","text":"Iets tasbaars wat die werk oplewer en oorhandig, soos 'n werkende bladsy of 'n verslag.","also":["lewerbares","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Vooruitskatting","text":"'n Voorspelling van wat waarskynlik gaan gebeur, soos wanneer die werk klaar sal wees, gebaseer op wat jy tot dusver weet.","also":["vooruitskattings","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Maatstaf (Metric)","text":"Enigiets wat jy oor tyd meet en dophou, soos bladsybesoeke of hoe lank dit neem om 'n fout reg te maak.","also":["maatstawwe","metric","metrics"]},{"id":"feedback","g":"plan","word":"Terugvoer","text":"Wat mense jou van jou werk sê, goed en sleg. Om dit vroeg en gereeld te kry, is die hart van Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Die waglys van idees en werk wat nog nie ingeplan is nie, met die belangrikste bo-aan. Aan niks daarin word gewerk voordat dit na Om te doen skuif nie."},{"id":"sprint","g":"agile","word":"Sprint","text":"'n Kort, vaste werktydperk (dikwels een of twee weke, nooit meer as 'n maand nie) met 'n doel en 'n ooreengekome stel kaarte om klaar te maak.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"'n Vinnige daaglikse inskakeling: wat elke spanlid gedoen het, wat hulle volgende doen en wat hulle keer. In Scrum word dit die daaglikse scrum genoem.","also":["standup","stand-ups","daily scrum","daily stand-up","daaglikse scrum"]},{"id":"kanban","g":"agile","word":"Kanban","text":"'n Manier van werk waar kaarte oor 'n bord se kolomme beweeg (soos Om te doen, Aan die gang, Klaar) en die span beperk hoeveel op 'n slag aan die gang is, sodat werk aan die vloei bly."},{"id":"wip","g":"agile","word":"WIP-limiet","text":"WIP is kort vir work in progress (werk aan die gang). 'n WIP-limiet is die meeste kaarte wat 'n kolom op 'n slag mag hou, sodat die span dinge klaarmaak voordat dit meer begin.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definisie van Klaar","text":"Die span se kort kontrolelys van wat “klaar” beteken, soos getoets en verduidelik, voordat 'n kaart aan jou oorhandig word. Sy tweeling, die Definisie van Gereed, sê wanneer 'n kaart duidelik genoeg is om te begin.","also":["Definition of Ready","DoD","DoR","definisie van klaar"]},{"id":"retro","g":"agile","word":"Terugblik","text":"'n Gereelde terugblik op hoe die span werk, om oor een of twee dinge ooreen te kom om volgende keer beter te doen. Kort vir retrospektief. In AI-gile stel 'n retro 'n verandering aan die span se werkswyse voor, en jy sê Gaan of Nog nie.","also":["terugblikke","retro","retrospektief"]},{"id":"swarm","g":"agile","word":"Swerm","text":"Almal aan dek: baie mense los ander werk om een dringende ding saam reg te maak tot dit uitgesorteer is. In AI-gile help elke span met een projek, en ander projekte wag intussen.","also":["swerm","swarm"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"In Scrum, die persoon wat die span help om goed te werk: ruim op wat hulle keer, hou vergaderings op koers en leer goeie gewoontes aan, sonder om iemand te baasspeel. In AI-gile sien die Lead Scrum Master kaarte raak wat vassit, stoot die spanne aan en herinner jou aan wat wag, oor elke projek heen.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"'n Manier van werk in klein stappies: bou 'n bietjie, wys gereeld regte resultate, leer uit wat mense sê en verander die plan soos jy aangaan, in plaas daarvan om alles vooraf te beplan.","also":["Agile development","agile ways of working","ratse ontwikkeling"]},{"id":"manifesto","g":"agile","word":"Agile-manifes (Agile Manifesto)","text":"'n Kort verklaring wat in 2001 deur sagtewaremakers geskryf is. Dit stel mense, werkende resultate, noue samewerking met kliënte en om op verandering te reageer bo swaar planne en papierwerk.","also":["Manifesto for Agile Software Development","Agile Manifesto"]},{"id":"waterfall","g":"agile","word":"Waterval (Waterfall)","text":"Die ouer manier van werk: beplan alles, bou dan alles, toets dan alles, een stadium na die ander. Veranderinge laat in die proses is moeilik en duur.","also":["waterfall model","watervalmodel"]},{"id":"iteration","g":"agile","word":"Iterasie","text":"Een ronde van iets bou, nagaan en verbeter. Agile werk is 'n ketting hiervan, en 'n sprint is een soort.","also":["iterasies","iteration","iterations"]},{"id":"increment","g":"agile","word":"Inkrement","text":"'n Nuwe werkende stuk wat in 'n sprint of werkronde by die produk gevoeg word en inpas by wat reeds daar was.","also":["inkremente","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"'n Gewilde Agile werkswyse: 'n klein span werk in kort sprints na 'n doel toe, met vaste rolle en 'n paar gereelde vergaderings om te beplan, na te gaan en te verbeter."},{"id":"scrumteam","g":"agile","word":"Scrum-span","text":"Die klein groep wat die werk in Scrum doen: 'n produkeienaar, 'n Scrum Master en die ontwikkelaars.","also":["Scrum-spanne","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum-geleenthede (Scrum events)","text":"Die gereelde vergaderings in Scrum: sprintbeplanning, die daaglikse scrum, die sprinthersiening en die retro. Baie mense noem hulle seremonies.","also":["seremonies","Scrum-seremonies","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprintbeplanning","text":"Die vergadering aan die begin van 'n sprint waar die span ooreenkom oor waarom die sprint saak maak, watter kaarte om aan te pak en hoe om te begin.","also":["beplanningsvergadering","planning meeting","sprint planning"]},{"id":"sprintgoal","g":"agile","word":"Sprintdoel","text":"Een sin wat sê waarvoor 'n sprint is. Klein take kan onderweg verander, solank die doel bereik word.","also":["sprintdoelwitte","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint-backlog","text":"Die kaarte wat vir die huidige sprint gekies is, met die span se plan om hulle te doen.","also":["sprint-backlogs","sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Produk-backlog","text":"Die volledige gerangskikte lys van alles wat vir die produk gebou kan word, die belangrikste bo-aan. Dit verander aanhoudend soos jy leer.","also":["produk-backlogs","product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Produkdoel","text":"Die groter resultaat waarheen die produk werk, wat die span help kies wat om volgende te doen.","also":["produkdoelwitte","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Backlog-verfyning (Backlog refinement)","text":"Gereeld deur die backlog gaan om kaarte op te ruim, op te deel, te rangskik en meer besonderhede by te voeg, sodat hulle gereed is om opgetel te word. Word ook backlog grooming genoem.","also":["backlog grooming","refinement","verfyning"]},{"id":"sprintreview","g":"agile","word":"Sprinthersiening (Sprint review)","text":"'n Vergadering aan die einde van 'n sprint waar die span wys wat dit voltooi het en hoor wat mense dink, om te besluit wat volgende kom.","also":["sprinthersienings","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Demonstrasie (Demo)","text":"Voltooide werk lewendig wys terwyl dit werk, aan die mense wat daarvoor gevra het.","also":["demonstrasies","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Tydblok (Timebox)","text":"'n Vaste hoeveelheid tyd vir iets. Wanneer dit om is, hou jy op, selfs al is nie alles klaar nie.","also":["tydblokke","timeboxed","timeboxes","timebox"]},{"id":"velocity","g":"agile","word":"Snelheid (Velocity)","text":"Hoeveel werk 'n span gewoonlik in 'n sprint afhandel, gebruik om te beplan hoeveel om volgende keer aan te pak. Dit is nie 'n telling van hoe hard mense werk nie.","also":["spansnelheid","team velocity"]},{"id":"capacity","g":"agile","word":"Kapasiteit","text":"Hoeveel werk die span in 'n tydperk kan aanpak, ná vakansies en ander take.","noTip":1},{"id":"burndown","g":"agile","word":"Afbrandgrafiek (Burndown chart)","text":"'n Grafiek van die werk wat in 'n sprint oor is en dag vir dag daal. As die lyn plat bly, sit iets vas.","also":["burndown","burn-down chart","burndown-grafiek"]},{"id":"burnup","g":"agile","word":"Opbrandgrafiek (Burnup chart)","text":"'n Grafiek van voltooide werk wat oor tyd styg, langs die totaal wat beplan is, sodat jy kan sien wanneer jy daar sal wees.","also":["burnup","burn-up chart","burnup-grafiek"]},{"id":"kanbanboard","g":"agile","word":"Kanban-bord","text":"Die bord self: 'n kolom vir elke stadium van die werk, met kaarte wat oor beweeg.","also":["Kanban-borde","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Trekstelsel (Pull system)","text":"'n Manier van werk waar nuwe werk net begin as iemand plek het om dit aan te pak, eerder as dat dit op iemand se reeds vol bord gedruk word.","also":["pull-based","trekgebaseer"]},{"id":"flow","g":"agile","word":"Vloei (Flow)","text":"Hoe glad werk oor die bord beweeg. Goeie vloei beteken kaarte bly beweeg eerder as om op te hoop.","also":["werkvloei","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Deurlooptyd (Lead time)","text":"Hoe lank dit neem van wanneer iemand om iets vra tot dit klaar is.","also":["lead times","deurlooptye"]},{"id":"cycletime","g":"agile","word":"Siklustyd (Cycle time)","text":"Hoe lank 'n kaart neem vanaf wanneer werk werklik daaraan begin tot dit klaar is.","also":["cycle times","siklustye"]},{"id":"throughput","g":"agile","word":"Deurset (Throughput)","text":"Hoeveel kaarte in 'n week, of in enige vaste tyd, klaar word.","also":["throughput rate","deursetsyfer"]},{"id":"bottleneck","g":"agile","word":"Bottelnek (Bottleneck)","text":"Die een stadium waar werk ophoop en alles daaragter vertraag, soos die nou nek van 'n bottel.","also":["bottelnekke","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swembaan (Swimlane)","text":"'n Ry oor die bord wat kaarte van een soort groepeer, soos dringende werk of een span se kaarte.","also":["swembane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean (skraal)","text":"'n Manier van werk wat vermorsing uitsny (alles wat nie die kliënt help nie) en die werk aan die vloei hou."},{"id":"waste","g":"agile","word":"Vermorsing (Waste)","text":"In Lean, enigiets wat moeite verg maar nie die kliënt help nie, soos wag, herwerk of dinge bou wat niemand gebruik nie.","noTip":1},{"id":"kaizen","g":"agile","word":"Deurlopende verbetering","text":"Heeltyd 'n bietjie beter word deur klein gereelde veranderinge, en dan nagaan of dit gehelp het. Retros is een manier om dit te doen. Ook kaizen genoem.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Selforganiserende span","text":"'n Span wat self besluit hoe om die werk te doen, eerder as dat iemand dit stap vir stap voorsê.","also":["selforganiserend","self-organising","self-managing team","selfbestuurde span"]},{"id":"crossfunc","g":"agile","word":"Kruisfunksionele span","text":"'n Span wat al die vaardighede het wat dit nodig het om die werk self klaar te maak, soos ontwerp, bou en toets.","also":["kruisfunksioneel","cross-functional"]},{"id":"spike","g":"agile","word":"Spike (navorsingsinsteek)","text":"'n Kort stukkie navorsing binne 'n vaste tydblok, om 'n vraag te beantwoord voordat jy jou aan die regte werk verbind.","also":["spikes"]},{"id":"rework","g":"agile","word":"Herwerk","text":"Werk oordoen omdat dit die eerste keer nie reg was nie.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Geskaleerde Agile (SAFe)","text":"Maniere om Agile oor baie spanne in 'n groot organisasie te gebruik. SAFe (die Scaled Agile Framework) is een bekende voorbeeld.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Die projek se lêergids met kode en sy volle geskiedenis van commits. Dit kan op jou rekenaar wees, op GitHub, of albei.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"'n Aparte werklyn in die kode, sodat veranderinge gemaak kan word sonder om aan die hoofweergawe te raak.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"'n Gestoorde kiekie van die kode, met 'n kort nota van wat verander het. Jy kan altyd na een teruggaan.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Jou gestoorde momentopnames (commits) van hierdie rekenaar na die gedeelde kopie aanlyn stuur, soos GitHub, sodat hulle gerugsteun is en ander hulle kan kry."},{"id":"merge","g":"build","word":"Merge","text":"Die veranderinge van een tak in 'n ander saamvoeg, gewoonlik terug in die hoofweergawe."},{"id":"pr","g":"build","word":"Pull request","text":"Vra dat 'n tak se veranderinge nagegaan en in die hoofweergawe saamgevoeg word. Sommige werwe noem dit 'n merge request.","also":["PR","PRs","merge request","saamvoegversoek"]},{"id":"refactor","g":"build","word":"Refactor","text":"Die kode opruim sonder om te verander wat dit doen: kleiner lêers, duideliker name, minder herhaling."},{"id":"bug","g":"build","word":"Bug","text":"Iets wat nie werk soos dit moet nie.","also":["bugs","fout","foute"]},{"id":"peerreview","g":"build","word":"Portuurhersiening","text":"'n Tweede paar oë: iemand anders as die skrywer gaan die werk na voordat dit by jou uitkom, sodat minder foute deurglip. In AI-gile gaan 'n ander KI elke kaart na.","also":["kodehersiening","peer review","code review"]},{"id":"code","g":"build","word":"Kode","text":"Die geskrewe opdragte wat 'n rekenaar sê wat om te doen. Ook bronkode genoem.","also":["bronkode","code","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programmeertaal","text":"'n Taal om kode in te skryf, soos JavaScript, Python of Java. Verskillende tale pas by verskillende take.","also":["programmeertale","programming language","programming languages"]},{"id":"developer","g":"build","word":"Ontwikkelaar (dev)","text":"Iemand wat kode skryf en verander. Ook 'n programmeerder of sagteware-ingenieur genoem.","also":["ontwikkelaars","developer","developers","programmeerder","programmeerders","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Sagteware","text":"Programme wat op rekenaars en fone loop, anders as die masjiene self (die hardeware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Kort vir toepassing: 'n program wat mense gebruik om iets gedoen te kry, op 'n foon, 'n rekenaar of in 'n webblaaier.","also":["apps","toepassing","toepassings","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web-app","text":"'n App wat in 'n webblaaier loop, sodat daar niks is om te installeer nie.","also":["web-apps","web apps","web application"]},{"id":"frontend","g":"build","word":"Voorkant (Front end)","text":"Die deel van 'n app wat jy sien en op klik: die skerms, knoppies en woorde, dikwels in jou blaaier.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Agterkant (Back end)","text":"Die agter-die-skerms-deel van 'n app wat die data hou en die werk doen wanneer jy iets klik, soos om jou wagwoord na te gaan.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack (voorkant en agterkant)","text":"Werk aan beide die voorkant en die agterkant.","also":["full-stack","full stack"]},{"id":"ui","g":"build","word":"Gebruikerskoppelvlak (UI)","text":"Wat 'n mens op die skerm sien en gebruik: uitleg, knoppies, kieslyste en teks.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"Gebruikerservaring (UX)","text":"Hoe dit voel om iets te gebruik: maklik, duidelik en aangenaam, of verwarrend en stadig.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Toeganklikheid (a11y)","text":"Dinge bruikbaar maak vir almal, ook mense wat nie goed kan sien nie, nie 'n muis kan gebruik nie of 'n skermleser gebruik.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Responsiewe ontwerp","text":"Bladsye so maak dat hulle op enige skermgrootte pas en goed werk, van 'n foon tot 'n groot monitor.","also":["responsief","responsive design"]},{"id":"designsys","g":"build","word":"Ontwerpstelsel (Design system)","text":"'n Gedeelde stel kleure, lettertipes, knoppies en reëls, sodat elke skerm dieselfde lyk en optree.","also":["ontwerpstelsels","design system","design systems"]},{"id":"architecture","g":"build","word":"Argitektuur","text":"Die algehele vorm van 'n stelsel: wat die hoofdele is en hoe hulle met mekaar praat."},{"id":"database","g":"build","word":"Databasis (DB)","text":"'n Georganiseerde bergplek vir inligting, soos 'n baie kragtige sigblad wat die app kan lees en verander.","also":["databasis","databasisse","database","databases","DB"]},{"id":"schema","g":"build","word":"Databasisskema","text":"Die uitleg van 'n databasis: watter tabelle inligting dit het en wat in elkeen gaan.","also":["skema","schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Kort vir gestruktureerde navraagtaal: die taal wat gebruik word om baie databasisse vir inligting te vra of dit te verander.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Inligting wat deur 'n rekenaar gehou word, soos name, bestellings of instellings.","also":["dataset","datasets","datastel","datastelle"],"noTip":1},{"id":"server","g":"build","word":"Bediener (Server)","text":"'n Rekenaar wat altyd aan is en versoeke van ander rekenaars beantwoord, soos om 'n webbladsy te stuur wanneer jy dit besoek.","also":["bedieners","server","servers"]},{"id":"client","g":"build","word":"Kliënt (Client)","text":"Die kant wat iets vra, gewoonlik jou blaaier of app, wat met 'n bediener praat. In besigheid beteken dit ook net 'n klant.","also":["kliënte","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Kort vir toepassingsprogrammeringskoppelvlak: 'n vaste spyskaart van versoeke wat een program aan 'n ander kan rig, soos om 'n weerdiens vir vandag se voorspelling te vra.","also":["APIs","application programming interface","toepassingsprogrammeringskoppelvlak"]},{"id":"endpoint","g":"build","word":"Eindpunt (Endpoint)","text":"Een item op 'n API se spyskaart: 'n webadres wat 'n program kan roep om iets te kry of te stuur.","also":["eindpunte","endpoint","endpoints"]},{"id":"integration","g":"build","word":"Integrasie","text":"Twee stelsels koppel sodat hulle saamwerk, soos jou winkel wat bestellings na jou rekeningkundige sagteware stuur.","also":["integrasies","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhaak (Webhook)","text":"'n Boodskap wat een stelsel self na 'n ander stuur die oomblik as iets gebeur, soos “betaling ontvang”.","also":["webhake","webhooks"]},{"id":"library","g":"build","word":"Biblioteek (Library)","text":"Gereedgemaakte kode wat iemand anders geskryf het en wat jy kan hergebruik in plaas daarvan om dit self te skryf.","also":["biblioteke","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Raamwerk (Framework)","text":"'n Gereedgemaakte struktuur om 'n app te bou wat baie bepaal van hoe die kode uitgelê word, soos 'n huisraam wat jy invul.","also":["raamwerke","framework","frameworks"]},{"id":"sdk","g":"build","word":"Sagteware-ontwikkelingstel (SDK)","text":"'n Gereedskapskis met hulpmiddels, kode en voorbeelde om sagteware vir een platform of diens te bou.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Sagteware-afhanklikheid","text":"'n Biblioteek of hulpmiddel wat jou kode nodig het om te werk. Om hulle op datum te hou is belangrik vir veiligheid.","also":["sagteware-afhanklikhede","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Pakket (Package)","text":"'n Bondel gereedgemaakte kode wat jy in 'n projek kan installeer en gebruik.","also":["pakkette","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Pakketbestuurder","text":"'n Hulpmiddel wat die pakkette haal en opdateer waarvan jou kode afhang. npm is 'n algemene een.","also":["pakketbestuurders","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Die mees gebruikte hulpmiddel om die geskiedenis van kodeveranderinge te hou, as commits en takke."},{"id":"github","g":"build","word":"GitHub","text":"'n Webwerf wat Git-repo's aanlyn hou, sodat spanne kode kan deel, veranderinge kan nagaan en werk kan volg."},{"id":"vcs","g":"build","word":"Weergawebeheer (Version control)","text":"'n Volledige geskiedenis hou van elke verandering aan die lêers, sodat jy kan sien wie wat verander het en kan teruggaan as dit nodig is. Git doen dit.","also":["bronbeheer","source control","version control","version control system"]},{"id":"clone","g":"build","word":"Kloon (Clone)","text":"Jou eie volledige kopie van 'n repo, met sy geskiedenis, op jou rekenaar maak.","also":["kloon","kloning","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Trek (Pull)","text":"Die nuutste commits van die gedeelde kopie (soos GitHub) na jou rekenaar haal. Die teenoorgestelde van push.","also":["git pull","pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Hooftak (Main branch)","text":"Die amptelike weergawe van die kode waaruit almal werk, dikwels main of master genoem.","also":["master branch","main branch","meestertak"]},{"id":"conflict","g":"build","word":"Saamvoegkonflik (Merge conflict)","text":"Wanneer twee veranderinge dieselfde reëls op verskillende maniere raak, sodat die rekenaar hulle nie kan saamvoeg nie en 'n mens moet kies.","also":["saamvoegkonflikte","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Verskil (Diff)","text":"'n Aansig wat presies wys wat tussen twee weergawes verander het: reëls bygevoeg en reëls weggeneem.","also":["diff","diffs","verskille"]},{"id":"fork","g":"build","word":"Aftak (Fork)","text":"Jou eie kopie van iemand anders se repo, wat jy kan verander sonder om die oorspronklike te raak.","also":["fork","forks","forked","aftakking"]},{"id":"script","g":"build","word":"Skrip (Script)","text":"'n Kort program wat een werkie self doen, soos om lêers op te ruim of die app te begin.","also":["skrips","scripts"],"noTip":1},{"id":"build","g":"build","word":"Bou (Build)","text":"Die kode omskep in iets wat gereed is om te loop, of die resultaat self wat gereed is om te loop.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompileer (Compile)","text":"Kode wat mense geskryf het vertaal in 'n vorm wat die rekenaar direk kan laat loop.","also":["compiler","kompileerder"]},{"id":"cli","g":"build","word":"Opdragreël (CLI)","text":"'n Teksvenster waar jy opdragte vir die rekenaar tik in plaas van te klik. Ook die terminaal genoem.","also":["command line","command-line","CLI","terminal","terminaal"]},{"id":"config","g":"build","word":"Konfigurasie (config)","text":"Die instellings wat bepaal hoe sagteware optree, apart van die kode gehou sodat dit maklik is om te verander.","also":["config","configuration","instellings"],"noTip":1},{"id":"envvar","g":"build","word":"Omgewingsveranderlike","text":"'n Instelling wat aan 'n program gegee word wanneer dit begin, dikwels vir adresse of wagwoorde gebruik sodat hulle nie in die kode geskryf word nie.","also":["omgewingsveranderlikes","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Ontfouting (Debugging)","text":"Naspeur hoekom iets nie werk nie, en dit regmaak.","also":["debug","debugged","ontfout"]},{"id":"pairing","g":"build","word":"Paarprogrammering","text":"Twee mense (of 'n mens en 'n KI) wat saam aan dieselfde kode werk, een wat tik en een wat nagaan.","also":["pair programming","pairing"]},{"id":"docs","g":"build","word":"Dokumentasie (docs)","text":"Geskrewe verduidelikings van hoe iets werk of hoe om dit te gebruik.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README (leesmy)","text":"Die eerste lêer om in 'n repo te lees: wat die projek is en hoe om dit aan die gang te kry.","also":["READMEs","leesmy"]},{"id":"legacy","g":"build","word":"Erfstelsel (Legacy system)","text":"'n Ouer stelsel wat nog gebruik word en moeilik is om te verander, dikwels omdat min mense dit nog verstaan.","also":["legacy systems","legacy code","erfstelsels"]},{"id":"techdebt","g":"build","word":"Tegniese skuld","text":"Kortpaaie wat nou tyd spaar maar latere veranderinge stadiger maak, soos 'n lening wat rente opbou. Herstrukturering betaal dit af.","also":["tech debt","technical debt"]},{"id":"test","g":"test","word":"Toets","text":"'n Toets dat iets werk soos dit moet. Sommige toetse laat die rekenaar self loop elke keer as die kode verander; ander is jy wat 'n voltooide kaart probeer voordat jy dit aanvaar.","also":["toetse","test","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kort vir gehalteversekering: alles wat gedoen word om seker te maak werk is reg voordat dit lewendig gaan. In AI-gile beteken dit die outomatiese toetse: wanneer QA rooi is, het iets misluk, en dit kan nie lewendig gaan voordat dit reggemaak is nie.","also":["gehaltebeheer","kwaliteitskontrole","KW"]},{"id":"testpile","g":"test","word":"Toetsstapel","text":"Die klaar kaarte wat wag dat jy hulle probeer, een na die ander. Aanvaar een of stuur dit terug met 'n nota, en die volgende een kom op.","also":["toetsstapels"]},{"id":"autotest","g":"test","word":"Outomatiese toets","text":"'n Toets wat die rekenaar self laat loop elke keer as die kode verander, om foute vroeg te vang.","also":["outomatiese toetse","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Handtoets","text":"'n Mens wat die werk met die hand probeer om te sien of dit optree soos dit moet.","also":["handtoetse","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Eenheidstoets (Unit test)","text":"'n Klein outomatiese toets van een klein stukkie kode op sy eie.","also":["eenheidstoetse","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Integrasietoets","text":"'n Toets dat verskeie dele reg saamwerk, nie net een op 'n slag nie.","also":["integrasietoetse","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Eind-tot-eind-toets (E2E)","text":"'n Toets wat soos 'n regte gebruiker van begin tot einde optree, soos inteken, koop en betaal.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"Gebruikersaanvaardingstoetsing (UAT)","text":"Die mense wat om die werk gevra het, probeer dit self en sê of dit doen wat hulle nodig het. AI-gile se toetsstapel is sy weergawe hiervan.","also":["UAT","acceptance testing","aanvaardingstoetsing"]},{"id":"regression","g":"test","word":"Regressie (Regression)","text":"Iets wat vroeër gewerk het maar ná 'n verandering gebreek het. Regressietoetse kyk of die ou goed nog werk.","also":["regressies","regressions","regression test","regression tests","regression testing","regressietoets"]},{"id":"smoke","g":"test","word":"Rooktoets (Smoke test)","text":"'n Baie vinnige toets of die hoofdinge enigsins werk, byvoorbeeld net nadat 'n verandering lewendig gaan. As dit misluk, stop en kyk.","also":["rooktoetse","smoke tests"]},{"id":"exploratory","g":"test","word":"Verkennende toetsing","text":"Die produk vryelik probeer en op verskillende maniere por, om probleme te vind wat beplande toetse sou mis.","also":["exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Toetsgeval (Test case)","text":"Een geskrewe scenario om te probeer: die stappe, en wat moet gebeur.","also":["toetsgevalle","test case","test cases"]},{"id":"coverage","g":"test","word":"Toetsdekking (Test coverage)","text":"Hoeveel van die kode deur outomatiese toetse nagegaan word. Meer is gewoonlik veiliger, maar hoë dekking alleen bewys nie dat dit goed werk nie.","also":["dekking","code coverage"]},{"id":"testdata","g":"test","word":"Toetsdata","text":"Versonne voorbeeldinligting wat tydens toetsing gebruik word, sodat niemand se private besonderhede blootgestel word nie.","also":["test fixtures","test data"]},{"id":"edgecase","g":"test","word":"Randgeval (Edge case)","text":"'n Ongewone situasie by die grense, soos 'n leë vorm of 'n naam met 'n apostrof, waar dinge dikwels breek.","also":["randgevalle","edge cases"]},{"id":"happypath","g":"test","word":"Gelukkige pad (Happy path)","text":"Die gewone roete waar alles reg verloop. Goeie toetsing probeer ook die ongelukkige paaie."},{"id":"perftest","g":"test","word":"Werkverrigtingtoetsing","text":"Nagaan hoe vinnig iets is en hoe goed dit onder druk regkom.","also":["performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Lastoetsing","text":"Nagaan hoe 'n stelsel regkom wanneer baie mense dit gelyktydig gebruik.","also":["load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Sekuriteitstoetsing","text":"Soek na swakhede waardeur iemand 'n stelsel kan misbruik of kan sien wat nie vir hulle bedoel is nie.","also":["security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Toeganklikheidstoetsing","text":"Nagaan dat mense met verskillende vermoëns die produk kan gebruik, ook met 'n skermleser of net 'n sleutelbord.","also":["accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"'n Outomatiese toets wat waarskynlike foute en slordige styl in kode raaksien, soos 'n speltoetser vir programme.","also":["linter","lint"]},{"id":"static","g":"test","word":"Statiese analise","text":"Kode vir probleme nagaan deur dit outomaties te lees, sonder om dit te laat loop.","also":["static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Wisselvallige toets (Flaky test)","text":"'n Toets wat soms slaag en soms misluk sonder duidelike rede, sodat jy dit nie ten volle kan vertrou nie.","also":["flaky tests","flaky test"]},{"id":"repro","g":"test","word":"Reproduseer (repro)","text":"'n Fout met opset weer laat gebeur deur dieselfde stappe te volg, sodat dit bestudeer en reggemaak kan word. Om daardie stappe neer te skryf is die nuttigste deel van 'n foutverslag.","also":["repro","reproduce","steps to reproduce","herskep"]},{"id":"severity","g":"test","word":"Erns (Severity)","text":"Hoe erg 'n probleem se uitwerking is, van 'n klein ergernis tot alles wat stop.","also":["severity","severity level","ernsgraad"]},{"id":"deploy","g":"change","word":"Deploy","text":"'n Nuwe weergawe van die sagteware kopieer na die rekenaars wat dit laat loop, soos 'n toetskopie of die lewendige diens."},{"id":"release","g":"change","word":"Vrystelling","text":"'n Benoemde bondel klaar werk wat saam regstreeks gaan, met kort notas oor wat verander het. 🚀 Vrystellings skryf die notas uit die klaar kaarte.","also":["vrystellings","release"]},{"id":"rollback","g":"change","word":"Rol terug","text":"Terugkeer na die laaste weergawe wat gewerk het wanneer 'n nuwe een moeilikheid veroorsaak. In AI-gile bring Rol terug die ontdoen-stappe wat by elke verandering geskryf is in een kontrolelys saam.","also":["terugrol","teruggerol","rollback"]},{"id":"live","g":"change","word":"Regstreeks","text":"Die regte weergawe wat mense gebruik, anders as 'n kopie om dinge op uit te probeer. Ontwikkelaars noem dit ook produksie.","also":["produksie","live"],"noTip":1},{"id":"change","g":"change","word":"Verandering","text":"'n Beplande verandering aan iets waarop mense staatmaak, eers neergeskryf: wat, hoekom, die risiko, wanneer, en hoe om dit te ontdoen. Begin een met 🔀 Dien 'n verandering in.","also":["veranderings","veranderingsversoek","change"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Iets wat kan skeefloop, met 'n telling vir hoe waarskynlik en hoe erg dit sou wees. ⚠️ Risiko's hou hulle in een lys, hoogste telling eerste, elk met 'n datum om weer te kyk.","also":["risiko's","risikoregister"]},{"id":"chgwin","g":"change","word":"Veranderingsvenster","text":"Die tye wanneer veranderings regstreeks mag gaan, soos 'n stil Dinsdagaand. Buite 'n venster kan 'n veranderingskaart nie klaargemaak word nie, tensy dit 'n noodgeval is.","also":["veranderingsvensters","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"'n Laaste toets net voordat 'n verandering lewendig gaan: elke persoon wat moet goedkeur, sê Go of No go. Dit gaan net voort as almal Go sê.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Goedkeuring","text":"Wag vir 'n ja voordat werk begin. 'n Kaart wat 'n vriend indien, of 'n verandering, wag in ✅ Goedkeurings totdat jy dit goedkeur of afkeur.","also":["goedkeurings"]},{"id":"quiettime","g":"change","word":"Stil tyd","text":"'n Tydperk, soos tydens 'n regstreekse uitsending, 'n demonstrasie of oornag, wanneer niks lewendig gaan nie. Die spanne werk en toets steeds, maar lewendig gaan wag tot dit eindig. Elders word dit 'n veranderingsvriesperiode genoem.","also":["stil tye","veranderingsbevriesing","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"'n Manier van werk waar die mense wat sagteware bou en die mense wat dit laat loop as een span werk, met baie outomatisering, sodat veranderinge gereeld en veilig lewendig gaan."},{"id":"cicd","g":"change","word":"CI/CD (deurlopende integrasie en aflewering)","text":"Almal se veranderinge word gereeld in die hoofweergawe saamgevoeg en elke keer outomaties nagegaan (deurlopende integrasie), sodat die sagteware altyd met die druk van 'n knoppie lewendig kan gaan (deurlopende aflewering).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","deurlopende integrasie","deurlopende aflewering"]},{"id":"contdeploy","g":"change","word":"Deurlopende ontplooiing","text":"Een stap verder as deurlopende aflewering: elke verandering wat die toetse slaag, gaan vanself lewendig, sonder dat jy 'n knoppie hoef te druk.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pyplyn (Pipeline)","text":"Die outomatiese reeks stappe wat 'n verandering op pad na lewendig deurloop, soos bou, toets, en dan ontplooi.","also":["pyplyne","pipelines"]},{"id":"environment","g":"change","word":"Omgewing (Environment)","text":"Een aparte kopie van die stelsel vir een doel, soos een om in te bou, een om in te toets en die lewendige een.","also":["omgewings","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Ontwikkelingsomgewing","text":"Die kopie waarin 'n ontwikkelaar werk, dikwels op hul eie rekenaar, waar dit niemand skaad as iets breek nie.","also":["dev environment","development environment"]},{"id":"testenv","g":"change","word":"Toetsomgewing","text":"'n Aparte kopie van die stelsel wat net vir toetsing gebruik word, sodat die regte diens nie geraak word nie.","also":["test environment","test environments"]},{"id":"staging","g":"change","word":"Staging-omgewing (Staging)","text":"'n Laaste kopie wat soos die lewendige een opgestel is, vir 'n finale toets voordat 'n verandering lewendig gaan.","also":["staging","staging environment"]},{"id":"artifact","g":"change","word":"Bou-artefak (Build artifact)","text":"Die lêer of bondel wat 'n bou oplewer, gereed om gestoor, nagegaan of lewendig gestel te word.","also":["build artifacts","artefak","artefakte"]},{"id":"hotfix","g":"change","word":"Hotfix (noodregstelling)","text":"'n Dringende regstelling wat vinnig lewendig gestel word, buite die gewone plan, omdat iets belangriks gebreek is.","also":["hotfixes","hotfix","noodregstelling","noodregstellings"]},{"id":"patch","g":"change","word":"Pleister (Patch)","text":"'n Klein opdatering wat 'n fout regmaak of 'n sekuriteitsgat toemaak. Dit is belangrik om sekuriteitspleisters vinnig toe te pas.","also":["patches","security patch","security patches","sekuriteitspleister"]},{"id":"version","g":"change","word":"Weergawenommer","text":"'n Etiket soos 2.4.1 wat sê watter uitgawe jy het. Dikwels verander die eerste nommer vir groot veranderinge en die laaste vir klein regmaaksels.","also":["weergawenommers","version numbers","version number","semantic versioning"]},{"id":"relnotes","g":"change","word":"Vrystellingsnotas (Release notes)","text":"'n Kort gewone lys van wat in 'n uitgawe verander het, vir die mense wat dit gebruik, met regmaaksels en bekende perke. Ook 'n changelog genoem.","also":["changelog","change log","veranderingslys"]},{"id":"flag","g":"change","word":"Feature flag (kenmerkskakelaar)","text":"'n Aan-en-af-skakelaar vir 'n kenmerk, sodat nuwe werk versteek lewendig kan gaan en aan (of weer af) gesit kan word sonder 'n nuwe uitgawe.","also":["feature flags","feature toggle","feature toggles","kenmerkskakelaar","kenmerkskakelaars"]},{"id":"rollfwd","g":"change","word":"Vorentoe-herstel (Roll forward)","text":"'n Slegte uitgawe regmaak deur vinnig 'n nuwe, verbeterde weergawe uit te bring in plaas van terug te gaan na die ou een.","also":["rolling forward","rolled forward","roll forward"]},{"id":"canary","g":"change","word":"Kanarie-vrystelling (Canary release)","text":"'n Verandering eers vir 'n klein groep lewendig stel, en eers vir almal wanneer dit goed lyk. Vernoem na die kanaries wat mynwerkers ondergronds saamgeneem het as vroeë waarskuwing.","also":["canary releases","canary","kanarie"]},{"id":"bluegreen","g":"change","word":"Blou-groen-ontplooiing","text":"Twee kopieë van die lewendige stelsel hou en mense in een slag na die nuwe een oorskakel, sodat jy dadelik kan terugskakel as dit skeefloop.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Ontplooiing sonder stilstand","text":"'n Nuwe weergawe lewendig stel sonder dat die diens ooit vir sy gebruikers stop.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Veranderingsbeheer (Change enablement)","text":"Veranderinge help slaag: die risiko opweeg, die regte goedkeuring kry en 'n goeie tyd kies. Ook veranderingsbestuur genoem.","also":["change management","veranderingsbestuur"]},{"id":"cab","g":"change","word":"Veranderingsadviesraad (CAB)","text":"'n Groep wat belangrike veranderinge deurkyk en ooreenkom of en wanneer hulle mag voortgaan.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Standaardverandering","text":"'n Laerisiko-verandering wat elke keer op dieselfde beproefde manier gedoen word, en daarom vooraf goedgekeur is.","also":["standaardveranderinge","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Normale verandering","text":"'n Verandering wat nagegaan en goedgekeur moet word voordat dit voortgaan.","also":["normale veranderinge","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Noodverandering","text":"'n Verandering wat dadelik moet gebeur om ernstige moeilikheid reg te maak of te voorkom, met 'n vinniger goedkeuring daarby.","also":["noodveranderinge","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Outomatisering","text":"Die rekenaar 'n herhaalde werkie self laat doen, sodat dit vinniger is en elke keer dieselfde gedoen word.","also":["automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktuur","text":"Die masjiene, netwerke en dienste waarop sagteware loop.","also":["infrastructure","infra"]},{"id":"iac","g":"change","word":"Infrastruktuur as kode (IaC)","text":"Jou bedieners en instellings in lêers beskryf wat saam met die kode gehou word, sodat hulle elke keer presies dieselfde herbou kan word.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Wolk (Cloud)","text":"Rekenaars, berging en dienste by 'n groot verskaffer oor die internet huur, in plaas daarvan om self die masjiene te besit.","also":["the cloud","cloud computing","die wolk","wolkdienste"]},{"id":"provider","g":"change","word":"Wolkverskaffer","text":"'n Maatskappy wat rekenaarkrag oor die internet verhuur, soos Amazon Web Services (AWS), Microsoft Azure of Google Cloud.","also":["wolkverskaffers","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Gasheerdiens (Hosting)","text":"Waar jou app of webwerf woon en loop sodat mense dit kan bereik, gewoonlik by 'n maatskappy gehuur.","also":["hosting","webgasheer","gasheerdienste"]},{"id":"domain","g":"change","word":"Domeinnaam","text":"Die webadres wat mense tik, soos example.com. Jy huur dit per jaar, so dit moet hernu word.","also":["domeinnaam","domain names","domain name","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Kort vir domeinnaamstelsel: die internet se adresboek, wat 'n naam soos example.com in die adres van die regte rekenaar omskep.","also":["domain name system"]},{"id":"container","g":"change","word":"Houer (Container)","text":"'n Verseëlde pakket met 'n app en alles wat dit nodig het, sodat dit op enige rekenaar dieselfde loop. Docker is die bekendste hulpmiddel.","also":["houers","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtuele masjien (VM)","text":"'n Nagebootste rekenaar wat binne 'n regte een loop, sodat een groot masjien as baie kan optree.","also":["VM","VMs","virtual machines","virtuele masjiene"]},{"id":"serverless","g":"change","word":"Bedienerloos (Serverless)","text":"Kode laat loop sonder om self enige bedieners te versorg: die verskaffer laat dit loop wanneer nodig en jy betaal vir wat jy gebruik."},{"id":"lb","g":"change","word":"Lasbalanseerder (Load balancer)","text":"Iets wat besoekers oor verskeie bedieners versprei, sodat nie een oorweldig word nie.","also":["lasbalanseerders","load balancers"]},{"id":"cache","g":"change","word":"Kasgeheue (Cache)","text":"'n Handige bergplek van onlangse resultate wat naby gehou word, sodat dieselfde ding nie weer gehaal of uitgewerk hoef te word nie. Om dit skoon te maak kan bladsye regmaak wat verouderd lyk.","also":["cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Inhoudsaflewerings-netwerk (CDN)","text":"'n Wêreldwye stel bedieners met kopieë van jou bladsye en prente naby jou besoekers, sodat dit vinnig laai.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migrasie","text":"Data of stelsels van 'n ou opstelling na 'n nuwe een skuif, of versigtig verander hoe 'n databasis uitgelê is.","also":["migrasies","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Diens","text":"Iets wat jy gebou het waarop mense staatmaak, soos 'n webwerf of 'n toep, wat opgepas word sodat dit aanhou werk. Merk “Hierdie projek is 'n diens” en sê wat dit bied, wie dit gebruik en wie op diens is.","also":["dienste"]},{"id":"uptimepct","g":"run","word":"Beskikbaarheidstyd (Uptime)","text":"Hoeveel van die tyd 'n diens werk, gewoonlik as 'n persentasie. Selfs 99,9% laat nog sowat 43 minute per maand toe waarin dit af is.","also":["uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"Beskikbaarheidskontrole","text":"'n Outomatiese kontrole, elke paar minute, dat jou diens nog antwoord. As dit 'n paar keer na mekaar misluk, maak AI-gile self 'n voorvalkaart oop.","also":["uptime checks","beskikbaarheidstoetse"]},{"id":"statuspage","g":"run","word":"Statusbladsy","text":"'n Openbare bladsy wat wys of 'n diens werk (groen, oranje of rooi) met die jongste nuus, sodat die mense wat dit gebruik kan kyk in plaas van vra.","also":["statusbladsye","status page"]},{"id":"desk","g":"run","word":"Dienslessenaar","text":"Waar vrae en berigte van die mense wat jou diens gebruik, inkom. AI-gile sorteer elkeen as 'n versoek, 'n voorval of 'n idee, en sê so as dit lyk na iets wat reeds aangemeld is.","also":["dienslessenaars","hulplessenaar","hulptoonbank"]},{"id":"svcrequest","g":"run","word":"Diensversoek","text":"Iemand wat vra vir iets gewoons, soos 'n nuwe rekening of 'n bietjie hulp, eerder as om te sê dat iets stukkend is. Dit wag sy beurt; 'n voorval gaan eerste.","also":["diensversoeke"]},{"id":"incident","g":"run","word":"Voorval","text":"Iets wat gebreek is of nie behoorlik werk nie vir die mense wat dit nou gebruik, soos die webwerf wat af of baie stadig is. 'n 🔥 voorvalkaart kry voorrang bo alles: om dit weer aan die gang te kry, kom eerste.","also":["voorvalle","incident"]},{"id":"major","g":"run","word":"Groot voorval","text":"'n Groot voorval: baie mense geraak, of geld of data in gevaar. Een knoppie sit elke span daarop (swerm), maak wakker wie ook al op diens is en vra elke 30 minute vir 'n statusopdatering.","also":["groot voorvalle","major incident"]},{"id":"oncall","g":"run","word":"Op diens","text":"Die een wees wat antwoord as iets breek, selfs in die nag. Elke diens het 'n spanlid op diens wat eerste wakker gemaak word vir sy voorvalle.","also":["diensbeurt","bystand","on call"]},{"id":"replyby","g":"run","word":"Antwoordtyd","text":"Hoe lank 'n kaart mag wag vir 'n eerste antwoord, byvoorbeeld 'n uur vir 'n voorval. Daarna kry dit 'n rooi horlosie, sodat niks stilletjies vergeet word nie. Ook 'n antwoordteiken genoem.","also":["antwoordtye","antwoordteiken","antwoordteikens"]},{"id":"postmortem","g":"run","word":"Nabetragting","text":"'n Kort terugblik na 'n voorval: wat gebeur het, wat gehelp het en wat om te verander, sonder om iemand te blameer. 'n Voorval kan nie sonder een gesluit word nie.","also":["nabetragtings","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Probleem","text":"Die verborge oorsaak agter een of meer voorvalle. 'n 🧩 Probleemkaart groepeer voorvalle wat aanhou terugkom, sodat die oorsaak gevind en vir goed reggemaak word.","also":["probleme"],"noTip":1},{"id":"rootcause","g":"run","word":"Grondoorsaak","text":"Die ware rede waarom iets gebreek het, nie net wat jy sien skeefloop het nie. Maak die grondoorsaak reg en die voorval hou op terugkom.","also":["grondoorsake","root cause"]},{"id":"workaround","g":"run","word":"Tydelike oplossing","text":"'n Manier om dinge aan die werk te hou totdat die regte oplossing gereed is, soos om iets te herbegin as dit vashaak. Dit word op die probleemkaart geskryf sodat niemand dit weer hoef uit te werk nie.","also":["tydelike oplossings","noodoplossing","workaround"]},{"id":"knownerror","g":"run","word":"Bekende fout","text":"'n Probleem waarvan die oorsaak verstaan word maar wat nog nie reggemaak is nie, gewoonlik met 'n omweg wat neergeskryf is. 🧩 Bekende foute lys hulle, sodat almal die omweg gebruik in plaas van weer te grawe.","also":["bekende foute","known error"]},{"id":"runbook","g":"run","word":"Draaiboek","text":"Stap-vir-stap-instruksies om 'n bekende soort moeilikheid reg te maak, sodat dit elke keer vinnig op dieselfde manier gedoen word. Na 'n groot voorval kan die span een voorstel wat jy kan goedkeur.","also":["draaiboeke","runbook"]},{"id":"ci","g":"run","word":"Konfigurasie-item","text":"Een ding waarop jou diens staatmaak, soos 'n bediener, 'n domein, 'n sertifikaat, 'n sleutel of 'n verskaffer. 🗂️ Konfigurasie-items lys hulle per diens, sodat jy kan sien wat 'n voorval raak en wat hernu of gerugsteun moet word.","also":["konfigurasie-items"]},{"id":"expiry","g":"run","word":"Vervaldatum","text":"Die datum waarop iets ophou werk tensy dit hernu word, soos 'n webwerf se sekuriteitsertifikaat of sy webadres. AI-gile hou hierdie datums dop en maak 30 dae vooraf een kaart om elkeen te hernu, sodat niks onverwags stop nie.","also":["vervaldatums","verval","vervaldatumwag"]},{"id":"backup","g":"run","word":"Rugsteun","text":"'n Gestoorde kopie van jou data van vroeër, om op terug te val as iets verlore raak of beskadig word. AI-gile maak elke dag 'n rugsteun van jou borde.","also":["rugsteune","backup"]},{"id":"restore","g":"run","word":"Herstel","text":"Data uit 'n rugsteun terugsit. 'n Rugsteun tel eers regtig as jy weet dit kan herstel word, so dit is die moeite werd om dit af en toe te probeer.","also":["herstel","teruggesit","restore"]},{"id":"svcreview","g":"run","word":"Dienshersiening","text":"'n Terugblik op een maand van 'n diens: voorvalle oopgemaak en opgelos, hoe vinnig mense 'n antwoord gekry het, beskikbaarheid en tokens gebruik. Die Maandelikse hersiening wys dit vir elke diens.","also":["dienshersienings","maandelikse hersiening","maandelikse hersienings"]},{"id":"accessreview","g":"run","word":"Toegangsondersoek","text":"Elke 90 dae nagaan wie nog kan inkom: deelskakels, vriende se rolle en gestoorde wagwoorde en sleutels. Jy hou of verwyder elkeen, sodat ou toegang nie bly hang nie.","also":["toegangsondersoeke"]},{"id":"improvements","g":"run","word":"Verbeteringslys","text":"Alles waarin die span besluit het om beter te word, op een plek: terugblikvoorstelle, hersieningsaksies en probleemoplossings, elk met sy status. Vind dit onder 📈 Verbeterings.","also":["verbeteringslyste","verbeterings"]},{"id":"tokencap","g":"run","word":"Tokenlimiet","text":"'n Maandelikse limiet op die tokens wat 'n diens se agente mag gebruik. By 80% kry jy 'n waarskuwing; by 100% wag hul agtergrondwerk tot volgende maand of totdat jy die limiet verhoog.","also":["tokenlimiete"]},{"id":"svcmgmt","g":"run","word":"Diensbestuur","text":"Alles wat daarmee gepaard gaan om 'n diens dag ná dag nuttig en werkend te hou vir die mense wat daarop staatmaak.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"'n Wyd gebruikte gids tot goeie diensbestuur, wat dinge soos voorvalle, probleme en veranderinge dek. Die naam het oorspronklik vir IT Infrastructure Library gestaan."},{"id":"itsm","g":"run","word":"IT-diensbestuur (ITSM)","text":"Tegnologie as 'n diens vir mense bestuur, met duidelike maniere om versoeke, voorvalle, veranderinge en verbeterings te hanteer.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Bestuurde diens","text":"'n Diens wat iemand anders vir jou bestuur en versorg, onder 'n ooreenkoms oor hoe goed dit moet werk.","also":["bestuurde dienste","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Dienseienaar","text":"Die persoon wat vir 'n diens as geheel verantwoordbaar is: hoe goed dit werk, wat dit kos en hoe dit verbeter.","also":["dienseienaars","service owner","service owners"]},{"id":"sla","g":"run","word":"Diensvlakooreenkoms (SLA)","text":"'n Geskrewe belofte aan kliënte oor hoe goed 'n diens sal werk, soos “99,9% van die tyd beskikbaar” of “binne 'n uur beantwoord”, dikwels met geld terug as dit nie nagekom word nie.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Diensvlakdoelwit (SLO)","text":"Die span se eie teiken vir hoe goed 'n diens oor 'n tydperk moet werk, gewoonlik 'n bietjie strenger as die SLA gestel om veilig te wees.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Diensvlakaanwyser (SLI)","text":"Die werklike meting wat jy teen 'n teiken nagaan, soos die deel van besoeke wat goed gelaai het.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Beskikbaarheid","text":"Of mense 'n diens kan gebruik wanneer hulle dit nodig het, dikwels gemeet as beskikbaarheidstyd.","also":["availability","high availability","hoë beskikbaarheid"]},{"id":"downtime","g":"run","word":"Stilstand (Downtime)","text":"Tyd wanneer 'n diens nie werk nie of afgeskakel is, beplan of nie.","also":["downtime","down time","stilstandtyd"]},{"id":"errorbudget","g":"run","word":"Foutbegroting (Error budget)","text":"Die klein hoeveelheid mislukking wat jou betroubaarheidsteiken toelaat. Solank daar nog oor is, kan jy met veranderinge risiko's neem; sodra dit op is, gaan jy stadiger aan.","also":["error budgets","error budget"]},{"id":"outage","g":"run","word":"Onderbreking (Outage)","text":"'n Tyd wanneer 'n diens vir sy gebruikers af is of erg gebreek is.","also":["outages","outage","diensonderbreking"]},{"id":"degraded","g":"run","word":"Verswak (Degraded)","text":"Dit werk, maar sleg: stadig, of met sommige dele wat nie werk nie.","also":["degraded service","verswakte diens"]},{"id":"monitoring","g":"run","word":"Monitering","text":"'n Diens heeltyd outomaties dophou, sodat probleme raakgesien word, verkieslik voordat gebruikers dit agterkom.","also":["monitoring"]},{"id":"observability","g":"run","word":"Waarneembaarheid (Observability)","text":"Hoe goed jy van buite kan sien wat binne 'n stelsel aangaan, met sy logboeke, syfers en spore.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Logboek (Log)","text":"'n Lopende dagboek wat 'n program hou van wat dit doen, gebruik om uit te werk wat verkeerd gegaan het.","also":["logboeke","logs","log","logging"],"noTip":1},{"id":"trace","g":"run","word":"Spoor (Trace)","text":"'n Rekord van hoe een versoek stap vir stap deur die verskillende dele van 'n stelsel reis, wat wys waar dit vertraag het.","also":["spore","traces","trace","tracing"]},{"id":"latency","g":"run","word":"Vertraging (Latency)","text":"Hoe lank iets neem om te antwoord, soos die wag tussen klik en die bladsy wat verskyn.","also":["latency","latensie"]},{"id":"alert","g":"run","word":"Waarskuwing (Alert)","text":"'n Outomatiese boodskap dat iets aandag nodig het, soos die webwerf wat nie antwoord nie.","also":["waarskuwings","alerts","alert","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Waarskuwingsmoegheid","text":"Wanneer daar soveel waarskuwings is dat mense hulle begin ignoreer, ook die belangrike.","also":["alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Kontrolepaneel (Dashboard)","text":"'n Skerm wat die belangrikste syfers en statusse in een oogopslag wys.","also":["dashboard","dashboards","paneelbord"],"noTip":1},{"id":"paging","g":"run","word":"Paging (noodoproep)","text":"Die diensdoende persoon dringend bel of wakker maak oor 'n probleem.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"Eskalasie","text":"Iemand met meer vaardigheid of gesag inskakel wanneer 'n saak nie op die huidige vlak, of nie vinnig genoeg, uitgesorteer kan word nie.","also":["escalation","escalate","escalated","eskaleer"]},{"id":"triage","g":"run","word":"Triage","text":"Inkomende kwessies vinnig sorteer volgens hoe dringend en belangrik hulle is, sodat die ergste eerste hanteer word.","also":["triaged"]},{"id":"impact","g":"run","word":"Impak (Impact)","text":"Hoeveel iets mense raak: hoeveel, en hoe erg.","noTip":1},{"id":"urgency","g":"run","word":"Dringendheid (Urgency)","text":"Hoe vinnig iets hanteer moet word. Impak en dringendheid saam bepaal die prioriteit.","noTip":1},{"id":"plevels","g":"run","word":"Prioriteitsvlakke (P1, P2…)","text":"Etikette vir hoe dringend 'n kwessie is. P1 is die ernstigste en vereis dadelike optrede.","also":["P1","P2","P3","P4","priority levels"]},{"id":"queue","g":"run","word":"Kaartjie-tou (Ticket queue)","text":"Die lys versoeke en voorvalle wat wag om opgetel te word.","also":["kaartjie-toue","ticket queues","ticket queue"]},{"id":"tiers","g":"run","word":"Eerste lyn en tweede lyn","text":"Vlakke van ondersteuning: eerste lyn neem die oproep en maak eenvoudige dinge reg; tweede lyn het dieper vaardighede vir moeiliker dinge. Ook vlak 1 en vlak 2 genoem.","also":["first-line support","tier 1","tier 2","eerstelyn","tweedelyn"]},{"id":"ic","g":"run","word":"Voorvalbevelvoerder (Incident commander)","text":"Die een persoon wat die reaksie op 'n voorval lei, sodat almal weet wie besluit en wie wat doen.","also":["incident commander","incident commanders","voorvalleier"]},{"id":"responsetime","g":"run","word":"Reaksietyd","text":"Hoe lank dit neem voordat iemand 'n versoek of voorval vir die eerste keer optel.","also":["response time","response times","reaksietye"]},{"id":"resolution","g":"run","word":"Oplossingstyd","text":"Hoe lank dit neem om 'n versoek of voorval ten volle uit te sorteer, van verslag tot reggemaak.","also":["resolution time","resolution times","time to resolve","oplossingstye"]},{"id":"mttr","g":"run","word":"Gemiddelde hersteltyd (MTTR)","text":"Gemiddeld hoe lank dit neem om 'n diens weer aan die gang te kry nadat dit gebreek het. MTTR kan effens verskillende dinge beteken, so sê wat jy meet.","also":["MTTR","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Gemiddelde tyd tussen foute (MTBF)","text":"Gemiddeld hoe lank 'n diens loop voordat iets breek.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Konfigurasiebestuur-databasis (CMDB)","text":"Die lys van al jou konfigurasie-items en hoe hulle verbind, sodat jy kan sien wat van wat afhang.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Bate (Asset)","text":"Enigiets van waarde wat jy besit of waarvoor jy betaal om die diens te laat loop, soos 'n skootrekenaar, 'n sagtewarelisensie of 'n domein.","also":["bates","assets","asset"],"noTip":1},{"id":"capplan","g":"run","word":"Kapasiteitsbeplanning","text":"Seker maak daar sal genoeg rekenaarkrag, berging en mense wees vir wat kom.","also":["capacity planning","capacity plan","kapasiteitsplan"]},{"id":"scaling","g":"run","word":"Skalering (Scaling)","text":"Meer gebruikers hanteer deur 'n masjien meer krag te gee (opskaal) of meer masjiene by te voeg (uitskaal).","also":["scaling","scale up","scale out","scaling up","scaling out","opskaal","uitskaal"]},{"id":"bcp","g":"run","word":"Besigheidskontinuïteit","text":"Planne om die belangrike dinge aan die gang te hou wanneer iets groots skeefloop, soos om 'n kantoor, 'n sleutelverskaffer of die rekenaars te verloor.","also":["business continuity","business continuity plan","kontinuïteitsplan"]},{"id":"dr","g":"run","word":"Rampherstel (DR)","text":"Die plan en hulpmiddels om 'n diens terug te kry ná iets ernstigs, soos om 'n hele datasentrum te verloor.","also":["DR","disaster recovery"]},{"id":"rto","g":"run","word":"Hersteltydteiken (RTO)","text":"Die langste wat 'n diens ná 'n ramp af mag wees voordat dit weer moet werk.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Herstelpuntteiken (RPO)","text":"Hoeveel onlangse data jy kan bekostig om te verloor, in tyd gemeet. 'n RPO van een uur beteken rugsteun ten minste elke uur.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Oortolligheid (Redundancy)","text":"Reserwes gereed hê, soos 'n tweede bediener, sodat een mislukking nie die diens stop nie.","also":["redundancy"]},{"id":"failover","g":"run","word":"Oorskakeling (Failover)","text":"Self oorskakel na 'n reserwestelsel wanneer die gewone een misluk.","also":["failover","fail over","foutoorskakeling"]},{"id":"spof","g":"run","word":"Enkele swakpunt (Single point of failure)","text":"Een deel wat, as dit breek, alles saam laat platval, omdat daar geen reserwe is nie.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Instandhoudingsvenster","text":"'n Beplande tyd wanneer 'n diens vir onderhoud gepouseer of stadig mag wees, vooraf aan gebruikers aangekondig.","also":["maintenance window","maintenance windows","planned maintenance","beplande onderhoud"]},{"id":"handover","g":"run","word":"Oordrag (Handover)","text":"Werk, kennis en verantwoordelikheid aan 'n ander persoon of span oorgee, sodat niks verlore gaan nie.","also":["handover","handovers","oorhandiging"]},{"id":"kb","g":"run","word":"Kennisbank (Knowledge base)","text":"'n Versameling hulpartikels en antwoorde, vir gebruikers en vir die span.","also":["kennisbanke","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Klanttevredenheid (CSAT)","text":"'n Telling van gebruikers wat sê hoe tevrede hulle was, dikwels gevra nadat 'n versoek gesluit is.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Verskaffer","text":"'n Eksterne maatskappy op wie jy staatmaak, soos jou gasheerverskaffer. Ook 'n vendor of derde party genoem.","also":["verskaffers","supplier","suppliers","vendor","vendors","third party","derde party"],"noTip":1},{"id":"retire","g":"run","word":"Diensafskaffing","text":"'n Diens vir goed en veilig afskakel: sy gebruikers inlig, sy data en toegang hanteer en sy koste stop.","also":["service retirement","retiring a service","diensuitfasering"]},{"id":"eol","g":"run","word":"Einde van lewensduur (EOL)","text":"Wanneer 'n produk nie meer opdaterings of ondersteuning van sy maker kry nie, sodat dit vervang moet word.","also":["EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Kuberveiligheid","text":"Stelsels en data beskerm teen inbraak, diefstal of skade.","also":["cybersecurity","cyber security","kubersekuriteit"]},{"id":"authn","g":"sec","word":"Verifiëring (Authentication)","text":"Nagaan wie iemand is, gewoonlik met 'n wagwoord of 'n kode. Dikwels verkort tot authn.","also":["authentication","authn","stawing"]},{"id":"authz","g":"sec","word":"Magtiging (Authorisation)","text":"Nagaan wat iemand mag doen sodra jy weet wie hulle is. Dikwels verkort tot authz.","also":["authorisation","authz","authorization"]},{"id":"mfa","g":"sec","word":"Multifaktor-verifiëring (MFA)","text":"Inteken met twee of meer bewyse, soos 'n wagwoord plus 'n kode op jou foon. Ook tweefaktor (2FA) genoem.","also":["MFA","2FA","two-factor","two-factor authentication","tweefaktor"]},{"id":"sso","g":"sec","word":"Enkelaanmelding (SSO)","text":"Een keer inteken om by baie stelsels in te kom, soos om jou werkrekening oral te gebruik.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Wagwoordbestuurder","text":"'n App wat sterk wagwoorde skep en dit vir jou onthou.","also":["wagwoordbestuurders","password manager","password managers"]},{"id":"secret","g":"sec","word":"Geheim (Secret)","text":"'n Wagwoord, sleutel of ander private kode wat 'n program gebruik om êrens in te kom. Dit mag nooit gedeel of in die kode geskryf word nie.","also":["geheime","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API-sleutel","text":"'n Geheime kode wat 'n program toelaat om 'n ander diens se API te gebruik, en wys wie dit gebruik (en daarvoor betaal).","also":["API-sleutels","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Toegangstoken (Access token)","text":"'n Tydelike pas wat bewys 'n program mag inkom, sodat dit nie elke keer jou wagwoord nodig het nie. Nie dieselfde as 'n KI-token nie.","also":["toegangstokens","access tokens","access token"]},{"id":"encryption","g":"sec","word":"Enkripsie (Encryption)","text":"Inligting deurmekaarmaak sodat net iemand met die regte sleutel dit kan lees.","also":["encrypted","encrypt","enkripteer","geënkripteer"]},{"id":"https","g":"sec","word":"HTTPS","text":"Die veilige manier waarop webbladsye reis, gewys deur die hangslot in jou blaaier, sodat niemand tussenin dit kan lees of verander nie."},{"id":"cert","g":"sec","word":"SSL/TLS-sertifikaat","text":"'n Digitale identiteitskaart waarmee 'n webwerf kan bewys wie dit is en HTTPS kan gebruik. Dit verval, so dit moet hernu word.","also":["TLS certificate","SSL certificate","certificate","certificates","sertifikaat","sertifikate"]},{"id":"permissions","g":"sec","word":"Toestemmings (Permissions)","text":"Die reëls oor wie wat mag sien of verander.","also":["permission","permissions","toestemming"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Minste voorreg (Least privilege)","text":"Elke persoon of program net die toegang gee wat hulle werklik nodig het, en net so lank as wat hulle dit nodig het.","also":["principle of least privilege","beginsel van minste voorreg"]},{"id":"rbac","g":"sec","word":"Rolgebaseerde toegangsbeheer (RBAC)","text":"Toegang volgens rol gee, soos kyker of redigeerder, eerder as persoon vir persoon.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Kwesbaarheid (Vulnerability)","text":"'n Swakheid wat iemand kan gebruik om in te breek of skade aan te rig.","also":["kwesbaarhede","vulnerabilities","vulnerability"]},{"id":"zeroday","g":"sec","word":"Zero-day (nuldagkwesbaarheid)","text":"'n Swakheid wat aanvallers ken voordat die vervaardigers enige tyd gehad het om dit reg te maak.","also":["zero-days","zero day","nuldag"]},{"id":"malware","g":"sec","word":"Kwaadwillige sagteware (Malware)","text":"Skadelike sagteware, soos virusse, gemaak om skade te doen, te spioeneer of te steel.","also":["malware"]},{"id":"ransomware","g":"sec","word":"Ransomware (losprys-sagteware)","text":"Kwaadwillige sagteware wat jou lêers sluit en geld eis om hulle te ontsluit. Goeie rugsteun is die beste verdediging.","also":["ransomware","ransomware attack","losprys-sagteware"]},{"id":"phishing","g":"sec","word":"Phishing (uitvissing)","text":"Vals boodskappe wat probeer om jou te flous om wagwoorde of geld weg te gee, of iets skadeliks oop te maak.","also":["phishing","phishing email","phishing emails","uitvissing"]},{"id":"socialeng","g":"sec","word":"Sosiale manipulasie (Social engineering)","text":"Mense, eerder as rekenaars, flous om toegang te gee, soos 'n vals oproep van “IT-ondersteuning”."},{"id":"firewall","g":"sec","word":"Vuurmuur (Firewall)","text":"'n Wag wat besluit watter netwerkverkeer mag inkom of uitgaan.","also":["vuurmure","firewalls","firewall"]},{"id":"vpn","g":"sec","word":"VPN","text":"Kort vir virtuele privaatnetwerk: 'n private, deurmekaargemaakte skakel oor die internet, dikwels gebruik om veilig by werkstelsels uit te kom.","also":["virtual private network","virtuele privaatnetwerk"]},{"id":"ddos","g":"sec","word":"Diensweiering (DoS, DDoS)","text":"'n Diens met soveel vals verkeer oorspoel dat regte mense dit nie kan gebruik nie. DDoS beteken dit kom van baie rekenaars gelyktydig.","also":["DoS","DDoS","denial of service","DDoS attack","DDoS-aanval"]},{"id":"pentest","g":"sec","word":"Penetrasietoets (pen test)","text":"Vriendelike kenners aanstel om te probeer inbreek, sodat swakhede gevind word voordat regte aanvallers hulle vind.","also":["pen test","pen testing","penetration testing","pentest","indringtoets"]},{"id":"audit","g":"sec","word":"Sekuriteitsoudit","text":"'n Noukeurige toets van hoe goed iets beskerm is, teenoor 'n lys van goeie praktyk.","also":["security audit","security audits","sekuriteitsoudits"]},{"id":"threatmodel","g":"sec","word":"Bedreigingsmodellering","text":"Deurdink wie iets kan aanval, hoe, en wat jy sou doen om hulle te keer.","also":["threat modelling","threat model","threat modeling","bedreigingsmodel"]},{"id":"breach","g":"sec","word":"Datalek (Data breach)","text":"Wanneer private inligting uitkom by mense wat dit nie behoort te hê nie, of verlore gaan of sonder toestemming verander word.","also":["data breach","data breaches","datalekke"]},{"id":"pii","g":"sec","word":"Persoonlike data","text":"Enige inligting oor 'n persoon wat geïdentifiseer kan word, soos 'n naam, e-posadres of ligging. Ook PII genoem.","also":["PII","personally identifiable information","persoonlike inligting"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Die Europese wet op persoonlike data (die VK het sy eie weergawe): versamel net wat jy nodig het, hou dit veilig, en laat mense hul eie sien of uitvee.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Databeskerming","text":"Persoonlike data behoorlik en binne die wet versorg.","also":["data protection","data protection law","databeskermingswet"]},{"id":"privacypolicy","g":"sec","word":"Privaatheidsbeleid","text":"'n Openbare bladsy wat sê watter persoonlike data jy versamel, hoekom, en wat jy daarmee doen.","also":["privacy policy","privacy statement","privacy notice","privaatheidsverklaring"]},{"id":"consent","g":"sec","word":"Toestemming (Consent)","text":"'n Persoon se duidelike, vrye ja dat hul data op 'n bepaalde manier gebruik word. Hulle kan dit enige tyd terugtrek.","also":["consent","opt-in","inwilliging"],"noTip":1},{"id":"cookie","g":"sec","word":"Koekie (Cookie)","text":"'n Klein lêer wat 'n webwerf in jou blaaier stoor om dinge te onthou, soos dat jy ingeteken is. Sommige het eers jou toestemming nodig.","also":["koekies","cookies","cookie"],"noTip":1},{"id":"minimisation","g":"sec","word":"Datavermindering (Data minimisation)","text":"Net die persoonlike data versamel en hou wat jy werklik vir die werk nodig het.","also":["data minimisation","data minimization","data-minimering"]},{"id":"retention","g":"sec","word":"Databewaring (Data retention)","text":"Hoe lank data gehou word voordat dit uitgevee word. Om dit nie langer as nodig te hou nie, is veiliger en dikwels wetlik verpligtend.","also":["data retention","retention period","bewaringstydperk"]},{"id":"anon","g":"sec","word":"Anonimisering","text":"Data so verander dat niemand daaruit redelikerwys meer geïdentifiseer kan word nie.","also":["anonymisation","anonymised","anonymization","anonymous data","geanonimiseer","anonieme data"]},{"id":"pseudo","g":"sec","word":"Pseudonimisering","text":"Name en ander besonderhede met kodes vervang, met 'n sleutel apart gehou om hulle terug te koppel. Dit is steeds persoonlike data.","also":["pseudonymisation","pseudonymised","pseudonymization","gepseudonimiseer"]},{"id":"dpa","g":"sec","word":"Dataverwerkingsooreenkoms (DPA)","text":"'n Kontrak wat sê hoe 'n verskaffer persoonlike data namens jou mag hanteer.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Databeskermings-impakbeoordeling (DPIA)","text":"'n Noukeurige blik, voordat jy begin, op hoe 'n plan om persoonlike data te gebruik mense kan raak en hoe om die risiko's te verlaag.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Ouditlogboek","text":"'n Rekord van wie wat gedoen het en wanneer, sodat dade later nagegaan kan word.","also":["audit log","audit logs","audit trail","ouditspoor"]},{"id":"compliance","g":"sec","word":"Nakoming (Compliance)","text":"Die wette, reëls en standaarde wat op jou van toepassing is volg, en kan wys dat jy dit doen.","also":["compliance","compliant","voldoening"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"'n Bekende internasionale standaard vir die bestuur van inligtingsekuriteit. Maatskappye kan daarteen gesertifiseer word.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"'n Amerikaanse verslag, deur eksterne ouditeurs nagegaan, wat wys dat 'n maatskappy kliëntdata behoorlik versorg.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"'n KI wat self aan 'n taak werk: lees die kode, maak veranderinge, laat toetse loop en doen verslag. Sy werk word steeds nagegaan.","also":["agents","agente"]},{"id":"token","g":"ai","word":"Token","text":"Die klein stukkies teks wat 'n KI lees en skryf, ongeveer driekwart van 'n woord elk. KI-gebruik word in tokens getel, so minder tokens laat meer van jou plan oor.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"'n Klein opdrag wat vanself op 'n bepaalde oomblik loop, byvoorbeeld wanneer 'n KI-sessie begin, sodat die span jou kommentaar hoor.","also":["hooks"]},{"id":"ai","g":"ai","word":"Kunsmatige intelligensie (KI)","text":"Rekenaarstelsels wat dinge doen waarvoor ons gewoonlik dink 'n mens nodig is, soos skryf, vrae beantwoord of prente herken.","also":["AI","artificial intelligence","KI"],"noTip":1},{"id":"ml","g":"ai","word":"Masjienleer (ML)","text":"'n Manier om rekenaars patrone uit baie voorbeelde te laat leer, in plaas daarvan om hulle presiese reëls te gee.","also":["machine learning","ML"]},{"id":"model","g":"ai","word":"Model","text":"Die opgeleide “brein” van 'n KI-stelsel, gebou deur uit groot getalle voorbeelde te leer. Modelle verskil in vaardigheid, spoed en prys.","also":["models","AI model","modelle","KI-model"],"noTip":1},{"id":"llm","g":"ai","word":"Groot taalmodel (LLM)","text":"'n KI-model wat op groot hoeveelhede teks opgelei is, sodat dit taal kan lees en skryf.","also":["LLM","LLMs","large language model"]},{"id":"genai","g":"ai","word":"Generatiewe KI","text":"KI wat nuwe dinge skep, soos teks, prente of kode, eerder as om dinge net te sorteer of raak te sien.","also":["GenAI","generative AI"]},{"id":"chatbot","g":"ai","word":"Kletsbot (Chatbot)","text":"'n Program waarmee jy in alledaagse taal praat, deur te tik of te praat.","also":["chatbots","chatbot","kletsbot"]},{"id":"prompt","g":"ai","word":"Prompt (opdrag)","text":"Wat jy vir 'n KI gee: jou vraag of instruksies, plus enigiets wat jy daarby gee. Duideliker prompts kry gewoonlik beter antwoorde.","also":["prompts","prompt"]},{"id":"prompteng","g":"ai","word":"Opdragontwerp (Prompt engineering)","text":"Die vaardigheid om opdragte te skryf wat betroubare, nuttige resultate gee.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Stelselopdrag (System prompt)","text":"Agtergrond-instruksies wat 'n KI kry voordat die gesprek begin, wat sy rol en reëls bepaal. Hulle weeg swaarder as wat jy tik.","also":["system prompt","system prompts","system instruction","system instructions","stelselinstruksie"]},{"id":"context","g":"ai","word":"Konteks (Context)","text":"Alles wat die KI kan sien terwyl dit werk: die instruksies, jou boodskappe, lêers wat dit gelees het en vroeëre antwoorde.","noTip":1},{"id":"ctxwin","g":"ai","word":"Konteksvenster (Context window)","text":"Hoeveel 'n KI op 'n slag in gedagte kan hou, gemeet in tokens. Daarna word ouer dele weggelaat of opgesom.","also":["context window","context windows","konteksvensters"]},{"id":"session","g":"ai","word":"Sessie (Session)","text":"Een werkgesprek met 'n KI, van begin tot einde. 'n Nuwe sessie begin met 'n skoon geheue.","also":["session","sessions","sessies"],"noTip":1},{"id":"memory","g":"ai","word":"Geheue (Memory)","text":"Notas wat 'n KI tussen sessies hou, sodat dit jou voorkeure en vorige besluite onthou.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallusinasie","text":"Wanneer 'n KI iets sê wat vol selfvertroue klink maar verdig of verkeerd is. Gaan belangrike feite na.","also":["hallucination","hallucinations","hallucinate","hallucinates","hallusinasies"]},{"id":"training","g":"ai","word":"Opleiding (Training)","text":"'n Model leer deur dit groot getalle voorbeelde te wys, voordat iemand dit gebruik.","also":["training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Opleidingsdata","text":"Die voorbeelde waaruit 'n model geleer het. Sy kennis hou op by die datum waarop die data versamel is.","also":["training data","training set","opleidingsdatastel"]},{"id":"cutoff","g":"ai","word":"Kennisafsnydatum","text":"Die datum waarop 'n KI se ingeboude kennis eindig. Dit sal nie van later dinge weet nie, tensy dit dit naslaan.","also":["knowledge cutoff","training cutoff","afsnydatum"]},{"id":"finetune","g":"ai","word":"Fyninstelling (Fine-tuning)","text":"Ekstra opleiding van 'n bestaande model op jou eie voorbeelde, om dit beter te maak by een besondere taak.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning","fyninstel"]},{"id":"inference","g":"ai","word":"Afleiding (Inference)","text":"'n KI-model wat werklik gebruik word om iets te beantwoord, anders as om opgelei te word.","also":["inference","model inference"]},{"id":"tooluse","g":"ai","word":"Gereedskapgebruik (Tool use)","text":"'n KI wat dinge kan doen, nie net praat nie: opdragte laat loop, lêers lees of die web deursoek, deur gereedskap wat die app daaraan gee.","also":["tool use","tool calling","tool call","tool calls","hulpmiddelgebruik"]},{"id":"subagent","g":"ai","word":"Subagent","text":"'n Helper-KI aan wie 'n hoof-KI 'n kleiner taak gee, en van wie dit die resultaat terugkry.","also":["subagents","sub-agent","subagente"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Verskeie KI's wat saam aan een stuk werk werk, elkeen met sy eie deel, soos 'n klein span.","also":["multi-agent system","multi-agent-stelsel"]},{"id":"autonomy","g":"ai","word":"Outonomie (Autonomy)","text":"Hoeveel 'n KI op sy eie mag doen voordat dit 'n mens moet vra.","also":["autonomy","autonomous","outonoom"]},{"id":"hitl","g":"ai","word":"Mens in die lus (Human in the loop)","text":"'n Mens betrokke hou om te kontroleer of goed te keur wat die KI by sleutelpunte doen. In AI-gile is dit jy.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Veiligheidsgrense (Guardrails)","text":"Perke en kontroles wat 'n KI se optrede veilig hou, soos goedkeuring nodig hê voordat iets lewendig gaan. Hulle verlaag die risiko van foute, maar sluit dit nie uit nie.","also":["guardrails","guardrail","veiligheidsrelings"]},{"id":"rag","g":"ai","word":"Opsoek-aangevulde generering (RAG)","text":"'n KI toelaat om dinge in jou eie dokumente na te slaan voordat dit antwoord, sodat sy antwoorde op jou feite rus.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Inbedding (Embedding)","text":"Teks omskep in 'n lys getalle wat die betekenis vasvang, sodat 'n rekenaar dinge kan vind wat soortgelyk beteken.","also":["embedding","embeddings","inbeddings"]},{"id":"vectordb","g":"ai","word":"Vektordatabasis","text":"'n Databasis gebou om daardie lyste getalle (inbeddings) deur te soek, om materiaal met 'n soortgelyke betekenis te vind.","also":["vector database","vector databases","vector store","vektorstoor"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"'n Gemeenskaplike manier om gereedskap en databronne by KI-apps in te prop, sodat 'n KI dit kan gebruik.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatuur (Temperature)","text":"'n Instelling vir hoe waaghalsig 'n KI se antwoorde is. Laag gee bestendiger, meer voorspelbare antwoorde; hoog gee meer gevarieerde. Geen van die twee maak dit altyd reg nie.","also":["temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodaal","text":"In staat om met meer as een soort inligting te werk, soos teks, prente en klank.","also":["multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Evaluering (eval)","text":"'n Beplande toets van hoe goed 'n KI by gekose voorbeelde vaar, sodat jy modelle of opdragte kan vergelyk.","also":["eval","evals","evaluasie"]},{"id":"bias","g":"ai","word":"Vooroordeel (Bias)","text":"Wanneer 'n KI (of 'n mens) onregverdig na een kant neig, dikwels weens dit waaruit dit geleer het.","also":["bias","biased","bevooroordeeld"],"noTip":1},{"id":"responsible","g":"ai","word":"Verantwoordelike KI","text":"KI regverdig, veilig en eerlik gebruik, met mense wat steeds vir die uitkomste verantwoordbaar is.","also":["responsible AI","ethical AI","etiese KI"]},{"id":"injection","g":"ai","word":"Opdrag-inspuiting (Prompt injection)","text":"'n Slenter waar verskuilde instruksies in 'n webbladsy of lêer probeer om 'n KI iets te laat doen wat sy gebruiker nie gevra het nie.","also":["prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Tempobeperking (Rate limit)","text":"'n Perk op hoeveel versoeke jy in 'n vasgestelde tyd aan 'n diens mag stuur. As jy daaroor gaan, moet jy wag.","also":["rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Gebruiksperk (Usage limit)","text":"Hoeveel KI-werk jou plan in 'n tydperk toelaat, waarna dit pouseer of meer kos.","also":["usage limit","usage limits","gebruiksperke"]},{"id":"vibe","g":"ai","word":"Vibe-kodering (Vibe coding)","text":"Sagteware grotendeels bou deur vir 'n KI te beskryf wat jy wil hê en dit die kode te laat skryf.","also":["vibe coding","vibe-coding"]},{"id":"budget","g":"money","word":"Begroting","text":"Die bedrag geld wat vir iets opsy gesit is.","also":["budget","budgets","begrotings"],"noTip":1},{"id":"costest","g":"money","word":"Kosteraming","text":"'n Beste raaiskoot van wat iets sal kos voordat jy begin.","also":["cost estimate","cost estimates","kosteramings"]},{"id":"roi","g":"money","word":"Opbrengs op belegging (ROI)","text":"Wat jy terugkry vergeleke met wat jy ingesit het. As dit positief is, was dit die moeite werd.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Totale eienaarskapkoste (TCO)","text":"Alles wat iets werklik oor sy hele leeftyd kos, nie net die koopprys nie: gebruik, ondersteuning, opgraderings en uiteindelik om dit uit gebruik te neem.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx en OpEx","text":"CapEx is geld wat vooraf bestee word aan dinge wat jy hou; OpEx is deurlopende uitgawes, soos maandelikse rekeninge.","also":["CapEx","OpEx","capital expenditure","operating expenditure","kapitaaluitgawe","bedryfsuitgawe"]},{"id":"subscription","g":"money","word":"Intekening (Subscription)","text":"Gereeld betaal, gewoonlik maandeliks of jaarliks, om iets te bly gebruik.","also":["subscription","subscriptions","intekeninge"],"noTip":1},{"id":"saas","g":"money","word":"Sagteware as 'n diens (SaaS)","text":"Sagteware wat jy aanlyn gebruik en waarvoor jy per intekening betaal, terwyl die maker dit vir jou bestuur.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Betaal soos jy gaan","text":"Net betaal vir wat jy gebruik, soos wolkdienste of KI-tokens.","also":["pay as you go","pay-as-you-go","usage-based pricing","gebruiksgebaseerde prys"]},{"id":"overage","g":"money","word":"Oorgebruik (Overage)","text":"Gebruik bo wat jou plan insluit, wat ekstra kan kos.","also":["overage","overages","overage charges","oorgebruikkoste"]},{"id":"billingalert","g":"money","word":"Faktureringswaarskuwing","text":"'n Boodskap wanneer besteding of gebruik 'n vlak bereik wat jy gekies het. Dit waarsku jou, maar stop nie altyd verdere koste nie.","also":["billing alert","billing alerts","spending alert","bestedingswaarskuwing"]},{"id":"freetier","g":"money","word":"Gratis vlak (Free tier)","text":"'n Gratis vlak van 'n betaalde diens, met perke. Handig om mee te begin.","also":["free tier","free plan","gratis plan"]},{"id":"pricing","g":"money","word":"Prysplan","text":"Die verskillende pakkette wat 'n diens verkoop, elkeen met sy eie prys en perke.","also":["pricing plan","pricing plans","price plan","prysplanne"]},{"id":"licence","g":"money","word":"Lisensie","text":"Die reëls oor hoe jy iets mag gebruik, kopieer, verander of deel wat iemand anders gemaak het, soos sagteware, lettertipes of prente.","also":["lisensies","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Oopbron (Open source)","text":"Sagteware waarvan die kode enigiemand kan lees, gebruik en dikwels gratis kan verander, onder die reëls van sy lisensie.","also":["open source","open-source","open source software","OSS","oopbronsagteware"]},{"id":"osslicence","g":"money","word":"Oopbronlisensie","text":"Die reëls wat by oopbronkode kom. Sommige laat jou byna enigiets doen (soos MIT); sommige vra dat jy ook jou veranderinge deel (soos GPL).","also":["open source licence","open source licences","MIT licence","GPL","oopbronlisensies"]},{"id":"proprietary","g":"money","word":"Proprietêr (Proprietary)","text":"In besit van 'n maatskappy en nie vry om te kopieer of te verander nie. Die teenoorgestelde van oopbron.","also":["proprietary","proprietary software","proprietêre sagteware","eiendomsagteware"]},{"id":"copyright","g":"money","word":"Outeursreg (Copyright)","text":"Die wetlike reg van 'n skepper om kopieë van hul werk te beheer, ook kode en geskrifte.","also":["copyright","copyrighted","kopiereg"],"noTip":1},{"id":"ip","g":"money","word":"Intellektuele eiendom (IP)","text":"Idees en skeppings wat die wet as besit beskou, soos kode, ontwerpe, name en logo's.","also":["IP","intellectual property","intellektuele eiendomsreg"]},{"id":"tos","g":"money","word":"Diensvoorwaardes","text":"Die reëls waarmee jy saamstem wanneer jy 'n diens gebruik.","also":["terms of service","terms and conditions","terms of use","terme en voorwaardes"]},{"id":"contract","g":"money","word":"Kontrak","text":"'n Geskrewe ooreenkoms tussen twee partye wat die wet sal afdwing.","also":["kontrakte","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Werkverklaring (SOW)","text":"'n Dokument wat presies uiteensit watter werk gedoen sal word, teen wanneer en vir hoeveel.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Vaste prys","text":"'n Ooreengekome prys vir die hele taak, hoe lank dit ook al neem.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Tyd en materiaal","text":"Betaal vir die ure wat werklik gewerk is en die goed wat werklik gebruik is, eerder as 'n vaste prys.","also":["time and materials","T&M"]},{"id":"invoice","g":"money","word":"Faktuur","text":"'n Rekening wat om betaling vra vir werk wat gedoen of goedere wat gelewer is.","also":["fakture","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Verskaffersopsluiting (Vendor lock-in)","text":"Wanneer dit so moeilik of duur is om van 'n verskaffer weg te beweeg dat jy by hulle vassit.","also":["vendor lock-in","lock-in","verskaffersopsluiting"]},{"id":"procurement","g":"money","word":"Verkryging (Procurement)","text":"Die proses om verskaffers te kies en by hulle te koop.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Dienskrediet (Service credit)","text":"Geld terug of 'n afslag wat jy kry wanneer 'n verskaffer sy SLA nie nakom nie.","also":["service credit","service credits","dienskrediet"]}]}};
